      show_main_ui && !is_fullscreen && (type() & TYPE_POPUP) == 0;

  command_updater_.UpdateCommandEnabled(IDC_OPEN_CURRENT_URL, show_main_ui);

  command_updater_.UpdateCommandEnabled(IDC_SHOW_AS_TAB,
