void ChromotingHost::ShutdownNetwork() {
  if (!context_->network_message_loop()->BelongsToCurrentThread()) {
    context_->network_message_loop()->PostTask(
        FROM_HERE, base::Bind(&ChromotingHost::ShutdownNetwork, this));
    return;
  }
  // Stop chromotocol session manager.
  if (session_manager_.get()) {
    session_manager_->Close();
    session_manager_.reset();
  }
  // Stop XMPP connection.
  if (signal_strategy_.get()) {
    signal_strategy_->Close();
    signal_strategy_.reset();
    for (StatusObserverList::iterator it = status_observers_.begin();
         it != status_observers_.end(); ++it) {
      (*it)->OnSignallingDisconnected();
    }
  }
  ShutdownRecorder();
}

static int apparmor_setprocattr(struct task_struct *task, char *name,
void *value, size_t size)
{
char *command, *args = value;
size_t arg_size;
int error;

if (size == 0)
return -EINVAL;
/* args points to a PAGE_SIZE buffer, AppArmor requires that
* the buffer must be null terminated or have size <= PAGE_SIZE -1
* so that AppArmor can null terminate them
*/
if (args[size - 1] != '\0') {
if (size == PAGE_SIZE)
return -EINVAL;
args[size] = '\0';
}

/* task can only write its own attributes */
if (current != task)
return -EACCES;

args = value;
args = strim(args);
command = strsep(&args, " ");
if (!args)
return -EINVAL;
args = skip_spaces(args);
if (!*args)
return -EINVAL;

arg_size = size - (args - (char *) value);
if (strcmp(name, "current") == 0) {
if (strcmp(command, "changehat") == 0) {
error = aa_setprocattr_changehat(args, arg_size,
!AA_DO_TEST);
} else if (strcmp(command, "permhat") == 0) {
error = aa_setprocattr_changehat(args, arg_size,
AA_DO_TEST);
} else if (strcmp(command, "changeprofile") == 0) {
error = aa_setprocattr_changeprofile(args, !AA_ONEXEC,
!AA_DO_TEST);
} else if (strcmp(command, "permprofile") == 0) {
error = aa_setprocattr_changeprofile(args, !AA_ONEXEC,
AA_DO_TEST);
} else if (strcmp(command, "permipc") == 0) {
error = aa_setprocattr_permipc(args);
} else {
struct common_audit_data sa;
COMMON_AUDIT_DATA_INIT(&sa, NONE);
sa.aad.op = OP_SETPROCATTR;
sa.aad.info = name;
sa.aad.error = -EINVAL;
			return aa_audit(AUDIT_APPARMOR_DENIED, NULL, GFP_KERNEL,
&sa, NULL);
}
} else if (strcmp(name, "exec") == 0) {
error = aa_setprocattr_changeprofile(args, AA_ONEXEC,
!AA_DO_TEST);
} else {
/* only support the "current" and "exec" process attributes */
return -EINVAL;
}
if (!error)
error = size;
return error;
}

static int wddx_stack_destroy(wddx_stack *stack)
{
register int i;

if (stack->elements) {
for (i = 0; i < stack->top; i++) {
			if (((st_entry *)stack->elements[i])->data)	{
zval_ptr_dtor(&((st_entry *)stack->elements[i])->data);
}
if (((st_entry *)stack->elements[i])->varname) {
efree(((st_entry *)stack->elements[i])->varname);
}
efree(stack->elements[i]);
}
efree(stack->elements);
}
return SUCCESS;
}

void lppTransposer (HANDLE_SBR_LPP_TRANS hLppTrans, /*!< Handle of lpp transposer  */
QMF_SCALE_FACTOR  *sbrScaleFactor, /*!< Scaling factors */
FIXP_DBL **qmfBufferReal, /*!< Pointer to pointer to real part of subband samples (source) */

FIXP_DBL *degreeAlias, /*!< Vector for results of aliasing estimation */
FIXP_DBL **qmfBufferImag, /*!< Pointer to pointer to imaginary part of subband samples (source) */
const int useLP,
const int timeStep, /*!< Time step of envelope */
const int firstSlotOffs, /*!< Start position in time */
const int lastSlotOffs, /*!< Number of overlap-slots into next frame */
const int nInvfBands, /*!< Number of bands for inverse filtering */
INVF_MODE *sbr_invf_mode, /*!< Current inverse filtering modes */
INVF_MODE *sbr_invf_mode_prev      /*!< Previous inverse filtering modes */
)
{
INT    bwIndex[MAX_NUM_PATCHES];
FIXP_DBL  bwVector[MAX_NUM_PATCHES]; /*!< pole moving factors */

int    i;
int    loBand, start, stop;
TRANSPOSER_SETTINGS *pSettings = hLppTrans->pSettings;
PATCH_PARAM *patchParam = pSettings->patchParam;
int    patch;

FIXP_SGL  alphar[LPC_ORDER], a0r, a1r;
FIXP_SGL  alphai[LPC_ORDER], a0i=0, a1i=0;
FIXP_SGL  bw = FL2FXCONST_SGL(0.0f);

int    autoCorrLength;

FIXP_DBL k1, k1_below=0, k1_below2=0;

ACORR_COEFS ac;
int    startSample;
int    stopSample;
int    stopSampleClear;

int comLowBandScale;
int ovLowBandShift;
int lowBandShift;
/*  int ovHighBandShift;*/
int targetStopBand;


alphai[0] = FL2FXCONST_SGL(0.0f);
alphai[1] = FL2FXCONST_SGL(0.0f);


startSample = firstSlotOffs * timeStep;
stopSample  = pSettings->nCols + lastSlotOffs * timeStep;


inverseFilteringLevelEmphasis(hLppTrans, nInvfBands, sbr_invf_mode, sbr_invf_mode_prev, bwVector);

stopSampleClear = stopSample;

autoCorrLength = pSettings->nCols + pSettings->overlap;

/* Set upper subbands to zero:
This is required in case that the patches do not cover the complete highband
(because the last patch would be too short).
Possible optimization: Clearing bands up to usb would be sufficient here. */
targetStopBand = patchParam[pSettings->noOfPatches-1].targetStartBand
+ patchParam[pSettings->noOfPatches-1].numBandsInPatch;

int memSize = ((64) - targetStopBand) * sizeof(FIXP_DBL);

if (!useLP) {
for (i = startSample; i < stopSampleClear; i++) {
FDKmemclear(&qmfBufferReal[i][targetStopBand], memSize);
FDKmemclear(&qmfBufferImag[i][targetStopBand], memSize);
}
} else
for (i = startSample; i < stopSampleClear; i++) {
FDKmemclear(&qmfBufferReal[i][targetStopBand], memSize);

}

/* init bwIndex for each patch */
  FDKmemclear(bwIndex, pSettings->noOfPatches*sizeof(INT));

/*
Calc common low band scale factor
*/
comLowBandScale = fixMin(sbrScaleFactor->ov_lb_scale,sbrScaleFactor->lb_scale);

ovLowBandShift =  sbrScaleFactor->ov_lb_scale - comLowBandScale;
lowBandShift   =  sbrScaleFactor->lb_scale - comLowBandScale;
/*  ovHighBandShift = firstSlotOffs == 0 ? ovLowBandShift:0;*/

/* outer loop over bands to do analysis only once for each band */

if (!useLP) {
start = pSettings->lbStartPatching;
stop = pSettings->lbStopPatching;
} else
{
start = fixMax(1, pSettings->lbStartPatching - 2);
stop = patchParam[0].targetStartBand;
}


for ( loBand = start; loBand <  stop; loBand++ ) {

FIXP_DBL  lowBandReal[(((1024)/(32))+(6))+LPC_ORDER];
FIXP_DBL *plowBandReal = lowBandReal;
FIXP_DBL **pqmfBufferReal = qmfBufferReal;
FIXP_DBL  lowBandImag[(((1024)/(32))+(6))+LPC_ORDER];
FIXP_DBL *plowBandImag = lowBandImag;
FIXP_DBL **pqmfBufferImag = qmfBufferImag;
int resetLPCCoeffs=0;
int dynamicScale = DFRACT_BITS-1-LPC_SCALE_FACTOR;
int acDetScale = 0; /* scaling of autocorrelation determinant */

for(i=0;i<LPC_ORDER;i++){
*plowBandReal++ = hLppTrans->lpcFilterStatesReal[i][loBand];
if (!useLP)
*plowBandImag++ = hLppTrans->lpcFilterStatesImag[i][loBand];
}

/*
Take old slope length qmf slot source values out of (overlap)qmf buffer
*/
if (!useLP) {
for(i=0;i<pSettings->nCols+pSettings->overlap;i++){
*plowBandReal++ = (*pqmfBufferReal++)[loBand];
*plowBandImag++ = (*pqmfBufferImag++)[loBand];
}
} else
{
/* pSettings->overlap is always even */
FDK_ASSERT((pSettings->overlap & 1) == 0);

for(i=0;i<((pSettings->overlap+pSettings->nCols)>>1);i++) {
*plowBandReal++ = (*pqmfBufferReal++)[loBand];
*plowBandReal++ = (*pqmfBufferReal++)[loBand];
}
if (pSettings->nCols & 1) {
*plowBandReal++ = (*pqmfBufferReal++)[loBand];
}
}

/*
Determine dynamic scaling value.
*/
dynamicScale = fixMin(dynamicScale, getScalefactor(lowBandReal, LPC_ORDER+pSettings->overlap) + ovLowBandShift);
dynamicScale = fixMin(dynamicScale, getScalefactor(&lowBandReal[LPC_ORDER+pSettings->overlap], pSettings->nCols) + lowBandShift);
if (!useLP) {
dynamicScale = fixMin(dynamicScale, getScalefactor(lowBandImag, LPC_ORDER+pSettings->overlap) + ovLowBandShift);
dynamicScale = fixMin(dynamicScale, getScalefactor(&lowBandImag[LPC_ORDER+pSettings->overlap], pSettings->nCols) + lowBandShift);
}
dynamicScale = fixMax(0, dynamicScale-1); /* one additional bit headroom to prevent -1.0 */

/*
Scale temporal QMF buffer.
*/
scaleValues(&lowBandReal[0], LPC_ORDER+pSettings->overlap, dynamicScale-ovLowBandShift);
scaleValues(&lowBandReal[LPC_ORDER+pSettings->overlap], pSettings->nCols, dynamicScale-lowBandShift);

if (!useLP) {
scaleValues(&lowBandImag[0], LPC_ORDER+pSettings->overlap, dynamicScale-ovLowBandShift);
scaleValues(&lowBandImag[LPC_ORDER+pSettings->overlap], pSettings->nCols, dynamicScale-lowBandShift);
}


if (!useLP) {
acDetScale += autoCorr2nd_cplx(&ac, lowBandReal+LPC_ORDER, lowBandImag+LPC_ORDER, autoCorrLength);
}
else
{
acDetScale += autoCorr2nd_real(&ac, lowBandReal+LPC_ORDER, autoCorrLength);
}

/* Examine dynamic of determinant in autocorrelation. */
acDetScale += 2*(comLowBandScale + dynamicScale);
acDetScale *= 2; /* two times reflection coefficent scaling */
acDetScale += ac.det_scale; /* ac scaling of determinant */

/* In case of determinant < 10^-38, resetLPCCoeffs=1 has to be enforced. */
if (acDetScale>126 ) {
resetLPCCoeffs = 1;
}


alphar[1] = FL2FXCONST_SGL(0.0f);
if (!useLP)
alphai[1] = FL2FXCONST_SGL(0.0f);

if (ac.det != FL2FXCONST_DBL(0.0f)) {
FIXP_DBL tmp,absTmp,absDet;

absDet = fixp_abs(ac.det);

if (!useLP) {
tmp = ( fMultDiv2(ac.r01r,ac.r12r) >> (LPC_SCALE_FACTOR-1) ) -
( (fMultDiv2(ac.r01i,ac.r12i) + fMultDiv2(ac.r02r,ac.r11r)) >> (LPC_SCALE_FACTOR-1) );
} else
{
tmp = ( fMultDiv2(ac.r01r,ac.r12r) >> (LPC_SCALE_FACTOR-1) ) -
( fMultDiv2(ac.r02r,ac.r11r) >> (LPC_SCALE_FACTOR-1) );
}
absTmp = fixp_abs(tmp);

/*
Quick check: is first filter coeff >= 1(4)
*/
{
INT scale;
FIXP_DBL result = fDivNorm(absTmp, absDet, &scale);
scale = scale+ac.det_scale;

if ( (scale > 0) && (result >= (FIXP_DBL)MAXVAL_DBL>>scale) ) {
resetLPCCoeffs = 1;
}
else {
alphar[1] = FX_DBL2FX_SGL(scaleValue(result,scale));
if((tmp<FL2FX_DBL(0.0f)) ^ (ac.det<FL2FX_DBL(0.0f))) {
alphar[1] = -alphar[1];
}
}
}

if (!useLP)
{
tmp = ( fMultDiv2(ac.r01i,ac.r12r) >> (LPC_SCALE_FACTOR-1) ) +
( (fMultDiv2(ac.r01r,ac.r12i) - (FIXP_DBL)fMultDiv2(ac.r02i,ac.r11r)) >> (LPC_SCALE_FACTOR-1) ) ;

absTmp = fixp_abs(tmp);

/*
Quick check: is second filter coeff >= 1(4)
*/
{
INT scale;
FIXP_DBL result = fDivNorm(absTmp, absDet, &scale);
scale = scale+ac.det_scale;

if ( (scale > 0) && (result >= /*FL2FXCONST_DBL(1.f)*/ (FIXP_DBL)MAXVAL_DBL>>scale) ) {
resetLPCCoeffs = 1;
}
else {
alphai[1] = FX_DBL2FX_SGL(scaleValue(result,scale));
if((tmp<FL2FX_DBL(0.0f)) ^ (ac.det<FL2FX_DBL(0.0f))) {
alphai[1] = -alphai[1];
}
}
}
}
}

alphar[0] =  FL2FXCONST_SGL(0.0f);
if (!useLP)
alphai[0] = FL2FXCONST_SGL(0.0f);

if ( ac.r11r != FL2FXCONST_DBL(0.0f) ) {

/* ac.r11r is always >=0 */
FIXP_DBL tmp,absTmp;

if (!useLP) {
tmp = (ac.r01r>>(LPC_SCALE_FACTOR+1)) +
(fMultDiv2(alphar[1],ac.r12r) + fMultDiv2(alphai[1],ac.r12i));
} else
{
if(ac.r01r>=FL2FXCONST_DBL(0.0f))
tmp = (ac.r01r>>(LPC_SCALE_FACTOR+1)) + fMultDiv2(alphar[1],ac.r12r);
else
tmp = -((-ac.r01r)>>(LPC_SCALE_FACTOR+1)) + fMultDiv2(alphar[1],ac.r12r);
}

absTmp = fixp_abs(tmp);

/*
Quick check: is first filter coeff >= 1(4)
*/

if (absTmp >= (ac.r11r>>1)) {
resetLPCCoeffs=1;
}
else {
INT scale;
FIXP_DBL result = fDivNorm(absTmp, fixp_abs(ac.r11r), &scale);
alphar[0] =  FX_DBL2FX_SGL(scaleValue(result,scale+1));

if((tmp>FL2FX_DBL(0.0f)) ^ (ac.r11r<FL2FX_DBL(0.0f)))
alphar[0] = -alphar[0];
}

if (!useLP)
{
tmp = (ac.r01i>>(LPC_SCALE_FACTOR+1)) +
(fMultDiv2(alphai[1],ac.r12r) - fMultDiv2(alphar[1],ac.r12i));

absTmp = fixp_abs(tmp);

/*
Quick check: is second filter coeff >= 1(4)
*/
if (absTmp >= (ac.r11r>>1)) {
resetLPCCoeffs=1;
}
else {
INT scale;
FIXP_DBL result = fDivNorm(absTmp, fixp_abs(ac.r11r), &scale);
alphai[0] = FX_DBL2FX_SGL(scaleValue(result,scale+1));
if((tmp>FL2FX_DBL(0.0f)) ^ (ac.r11r<FL2FX_DBL(0.0f)))
alphai[0] = -alphai[0];
}
}
}


if (!useLP)
{
/* Now check the quadratic criteria */
if( (fMultDiv2(alphar[0],alphar[0]) + fMultDiv2(alphai[0],alphai[0])) >= FL2FXCONST_DBL(0.5f) )
resetLPCCoeffs=1;
if( (fMultDiv2(alphar[1],alphar[1]) + fMultDiv2(alphai[1],alphai[1])) >= FL2FXCONST_DBL(0.5f) )
resetLPCCoeffs=1;
}

if(resetLPCCoeffs){
alphar[0] = FL2FXCONST_SGL(0.0f);
alphar[1] = FL2FXCONST_SGL(0.0f);
if (!useLP)
{
alphai[0] = FL2FXCONST_SGL(0.0f);
alphai[1] = FL2FXCONST_SGL(0.0f);
}
}

if (useLP)
{

/* Aliasing detection */
if(ac.r11r==FL2FXCONST_DBL(0.0f)) {
k1 = FL2FXCONST_DBL(0.0f);
}
else {
if ( fixp_abs(ac.r01r) >= fixp_abs(ac.r11r) ) {
if ( fMultDiv2(ac.r01r,ac.r11r) < FL2FX_DBL(0.0f)) {
k1 = (FIXP_DBL)MAXVAL_DBL /*FL2FXCONST_SGL(1.0f)*/;
}else {
/* Since this value is squared later, it must not ever become -1.0f. */
k1 = (FIXP_DBL)(MINVAL_DBL+1) /*FL2FXCONST_SGL(-1.0f)*/;
}
}
else {
INT scale;
FIXP_DBL result = fDivNorm(fixp_abs(ac.r01r), fixp_abs(ac.r11r), &scale);
k1 = scaleValue(result,scale);

if(!((ac.r01r<FL2FX_DBL(0.0f)) ^ (ac.r11r<FL2FX_DBL(0.0f)))) {
k1 = -k1;
}
}
}
if(loBand > 1){
/* Check if the gain should be locked */
FIXP_DBL deg = /*FL2FXCONST_DBL(1.0f)*/ (FIXP_DBL)MAXVAL_DBL - fPow2(k1_below);
degreeAlias[loBand] = FL2FXCONST_DBL(0.0f);
if (((loBand & 1) == 0) && (k1 < FL2FXCONST_DBL(0.0f))){
if (k1_below < FL2FXCONST_DBL(0.0f)) { /* 2-Ch Aliasing Detection */
degreeAlias[loBand] = (FIXP_DBL)MAXVAL_DBL /*FL2FXCONST_DBL(1.0f)*/;
if ( k1_below2 > FL2FXCONST_DBL(0.0f) ) { /* 3-Ch Aliasing Detection */
degreeAlias[loBand-1] = deg;
}
}
else if ( k1_below2 > FL2FXCONST_DBL(0.0f) ) { /* 3-Ch Aliasing Detection */
degreeAlias[loBand] = deg;
}
}
if (((loBand & 1) == 1) && (k1 > FL2FXCONST_DBL(0.0f))){
if (k1_below > FL2FXCONST_DBL(0.0f)) { /* 2-CH Aliasing Detection */
degreeAlias[loBand] = (FIXP_DBL)MAXVAL_DBL /*FL2FXCONST_DBL(1.0f)*/;
if ( k1_below2 < FL2FXCONST_DBL(0.0f) ) { /* 3-CH Aliasing Detection */
degreeAlias[loBand-1] = deg;
}
}
else if ( k1_below2 < FL2FXCONST_DBL(0.0f) ) { /* 3-CH Aliasing Detection */
degreeAlias[loBand] = deg;
}
}
}
/* remember k1 values of the 2 QMF channels below the current channel */
k1_below2 = k1_below;
k1_below = k1;
}

patch = 0;

while ( patch < pSettings->noOfPatches ) { /* inner loop over every patch */

int hiBand = loBand + patchParam[patch].targetBandOffs;

if ( loBand < patchParam[patch].sourceStartBand
|| loBand >= patchParam[patch].sourceStopBand
//|| hiBand >= hLppTrans->pSettings->noChannels
) {
/* Lowband not in current patch - proceed */
patch++;
continue;
}


FDK_ASSERT( hiBand < (64) );

/* bwIndex[patch] is already initialized with value from previous band inside this patch */
      while (hiBand >= pSettings->bwBorders[bwIndex[patch]])
bwIndex[patch]++;

/*
Filter Step 2: add the left slope with the current filter to the buffer
pure source values are already in there
*/
bw = FX_DBL2FX_SGL(bwVector[bwIndex[patch]]);

a0r = FX_DBL2FX_SGL(fMult(bw,alphar[0])); /* Apply current bandwidth expansion factor */


if (!useLP)
a0i = FX_DBL2FX_SGL(fMult(bw,alphai[0]));
bw =  FX_DBL2FX_SGL(fPow2(bw));
a1r = FX_DBL2FX_SGL(fMult(bw,alphar[1]));
if (!useLP)
a1i = FX_DBL2FX_SGL(fMult(bw,alphai[1]));



/*
Filter Step 3: insert the middle part which won't be windowed
*/

if ( bw <= FL2FXCONST_SGL(0.0f) ) {
if (!useLP) {
int descale = fixMin(DFRACT_BITS-1, (LPC_SCALE_FACTOR+dynamicScale));
for(i = startSample; i < stopSample; i++ ) {
qmfBufferReal[i][hiBand] = lowBandReal[LPC_ORDER+i]>>descale;
qmfBufferImag[i][hiBand] = lowBandImag[LPC_ORDER+i]>>descale;
}
} else
{
int descale = fixMin(DFRACT_BITS-1, (LPC_SCALE_FACTOR+dynamicScale));
for(i = startSample; i < stopSample; i++ ) {
qmfBufferReal[i][hiBand] = lowBandReal[LPC_ORDER+i]>>descale;
}
}
}
else { /* bw <= 0 */

if (!useLP) {
int descale = fixMin(DFRACT_BITS-1, (LPC_SCALE_FACTOR+dynamicScale));
#ifdef FUNCTION_LPPTRANSPOSER_func1
lppTransposer_func1(lowBandReal+LPC_ORDER+startSample,lowBandImag+LPC_ORDER+startSample,
qmfBufferReal+startSample,qmfBufferImag+startSample,
stopSample-startSample, (int) hiBand,
dynamicScale,descale,
a0r, a0i, a1r, a1i);
#else
for(i = startSample; i < stopSample; i++ ) {
FIXP_DBL accu1, accu2;

accu1 = (fMultDiv2(a0r,lowBandReal[LPC_ORDER+i-1]) - fMultDiv2(a0i,lowBandImag[LPC_ORDER+i-1]) +
fMultDiv2(a1r,lowBandReal[LPC_ORDER+i-2]) - fMultDiv2(a1i,lowBandImag[LPC_ORDER+i-2]))>>dynamicScale;
accu2 = (fMultDiv2(a0i,lowBandReal[LPC_ORDER+i-1]) + fMultDiv2(a0r,lowBandImag[LPC_ORDER+i-1]) +
fMultDiv2(a1i,lowBandReal[LPC_ORDER+i-2]) + fMultDiv2(a1r,lowBandImag[LPC_ORDER+i-2]))>>dynamicScale;

qmfBufferReal[i][hiBand] = (lowBandReal[LPC_ORDER+i]>>descale) + (accu1<<1);
qmfBufferImag[i][hiBand] = (lowBandImag[LPC_ORDER+i]>>descale) + (accu2<<1);
}
#endif
} else
{
int descale = fixMin(DFRACT_BITS-1, (LPC_SCALE_FACTOR+dynamicScale));

FDK_ASSERT(dynamicScale >= 0);
for(i = startSample; i < stopSample; i++ ) {
FIXP_DBL accu1;

accu1 = (fMultDiv2(a0r,lowBandReal[LPC_ORDER+i-1]) + fMultDiv2(a1r,lowBandReal[LPC_ORDER+i-2]))>>dynamicScale;

qmfBufferReal[i][hiBand] = (lowBandReal[LPC_ORDER+i]>>descale) + (accu1<<1);
}
}
} /* bw <= 0 */

patch++;

} /* inner loop over patches */

/*
* store the unmodified filter coefficients if there is
* an overlapping envelope
*****************************************************************/


} /* outer loop over bands (loBand) */

if (useLP)
{
for ( loBand = pSettings->lbStartPatching; loBand <  pSettings->lbStopPatching; loBand++ ) {
patch = 0;
while ( patch < pSettings->noOfPatches ) {

UCHAR hiBand = loBand + patchParam[patch].targetBandOffs;

if ( loBand < patchParam[patch].sourceStartBand
|| loBand >= patchParam[patch].sourceStopBand
|| hiBand >= (64) /* Highband out of range (biterror) */
) {
/* Lowband not in current patch or highband out of range (might be caused by biterrors)- proceed */
patch++;
continue;
}

if(hiBand != patchParam[patch].targetStartBand)
degreeAlias[hiBand] = degreeAlias[loBand];

patch++;
}
}/* end  for loop */
}

for (i = 0; i < nInvfBands; i++ ) {
hLppTrans->bwVectorOld[i] = bwVector[i];
}

/*
set high band scale factor
*/
sbrScaleFactor->hb_scale = comLowBandScale-(LPC_SCALE_FACTOR);

}

int ParseDsdiffHeaderConfig (FILE *infile, char *infilename, char *fourcc, WavpackContext *wpc, WavpackConfig *config)
{
int64_t infilesize, total_samples;
DFFFileHeader dff_file_header;
DFFChunkHeader dff_chunk_header;
uint32_t bcount;

infilesize = DoGetFileSize (infile);
memcpy (&dff_file_header, fourcc, 4);

if ((!DoReadFile (infile, ((char *) &dff_file_header) + 4, sizeof (DFFFileHeader) - 4, &bcount) ||
bcount != sizeof (DFFFileHeader) - 4) || strncmp (dff_file_header.formType, "DSD ", 4)) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &dff_file_header, sizeof (DFFFileHeader))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}

#if 1   // this might be a little too picky...
WavpackBigEndianToNative (&dff_file_header, DFFFileHeaderFormat);

if (infilesize && !(config->qmode & QMODE_IGNORE_LENGTH) &&
dff_file_header.ckDataSize && dff_file_header.ckDataSize + 1 && dff_file_header.ckDataSize + 12 != infilesize) {
error_line ("%s is not a valid .DFF file (by total size)!", infilename);
return WAVPACK_SOFT_ERROR;
}

if (debug_logging_mode)
error_line ("file header indicated length = %lld", dff_file_header.ckDataSize);

#endif

// loop through all elements of the DSDIFF header
// (until the data chuck) and copy them to the output file

while (1) {
if (!DoReadFile (infile, &dff_chunk_header, sizeof (DFFChunkHeader), &bcount) ||
bcount != sizeof (DFFChunkHeader)) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &dff_chunk_header, sizeof (DFFChunkHeader))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}

WavpackBigEndianToNative (&dff_chunk_header, DFFChunkHeaderFormat);

if (debug_logging_mode)
error_line ("chunk header indicated length = %lld", dff_chunk_header.ckDataSize);

if (!strncmp (dff_chunk_header.ckID, "FVER", 4)) {
uint32_t version;

if (dff_chunk_header.ckDataSize != sizeof (version) ||
!DoReadFile (infile, &version, sizeof (version), &bcount) ||
bcount != sizeof (version)) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, &version, sizeof (version))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}

WavpackBigEndianToNative (&version, "L");

if (debug_logging_mode)
error_line ("dsdiff file version = 0x%08x", version);
}
else if (!strncmp (dff_chunk_header.ckID, "PROP", 4)) {
char *prop_chunk;

if (dff_chunk_header.ckDataSize < 4 || dff_chunk_header.ckDataSize > 1024) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}

if (debug_logging_mode)
error_line ("got PROP chunk of %d bytes total", (int) dff_chunk_header.ckDataSize);

prop_chunk = malloc ((size_t) dff_chunk_header.ckDataSize);

if (!DoReadFile (infile, prop_chunk, (uint32_t) dff_chunk_header.ckDataSize, &bcount) ||
bcount != dff_chunk_header.ckDataSize) {
error_line ("%s is not a valid .DFF file!", infilename);
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}
else if (!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, prop_chunk, (uint32_t) dff_chunk_header.ckDataSize)) {
error_line ("%s", WavpackGetErrorMessage (wpc));
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}

if (!strncmp (prop_chunk, "SND ", 4)) {
char *cptr = prop_chunk + 4, *eptr = prop_chunk + dff_chunk_header.ckDataSize;
uint16_t numChannels = 0, chansSpecified, chanMask = 0;
                uint32_t sampleRate;

while (eptr - cptr >= sizeof (dff_chunk_header)) {
memcpy (&dff_chunk_header, cptr, sizeof (dff_chunk_header));
cptr += sizeof (dff_chunk_header);
WavpackBigEndianToNative (&dff_chunk_header, DFFChunkHeaderFormat);

if (dff_chunk_header.ckDataSize > 0 && dff_chunk_header.ckDataSize <= eptr - cptr) {
if (!strncmp (dff_chunk_header.ckID, "FS  ", 4) && dff_chunk_header.ckDataSize == 4) {
memcpy (&sampleRate, cptr, sizeof (sampleRate));
WavpackBigEndianToNative (&sampleRate, "L");
cptr += dff_chunk_header.ckDataSize;

if (debug_logging_mode)
error_line ("got sample rate of %u Hz", sampleRate);
}
else if (!strncmp (dff_chunk_header.ckID, "CHNL", 4) && dff_chunk_header.ckDataSize >= 2) {
memcpy (&numChannels, cptr, sizeof (numChannels));
WavpackBigEndianToNative (&numChannels, "S");
cptr += sizeof (numChannels);

chansSpecified = (int)(dff_chunk_header.ckDataSize - sizeof (numChannels)) / 4;

if (numChannels < chansSpecified || numChannels < 1 || numChannels > 256) {
error_line ("%s is not a valid .DFF file!", infilename);
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}

while (chansSpecified--) {
if (!strncmp (cptr, "SLFT", 4) || !strncmp (cptr, "MLFT", 4))
chanMask |= 0x1;
else if (!strncmp (cptr, "SRGT", 4) || !strncmp (cptr, "MRGT", 4))
chanMask |= 0x2;
else if (!strncmp (cptr, "LS  ", 4))
chanMask |= 0x10;
else if (!strncmp (cptr, "RS  ", 4))
chanMask |= 0x20;
else if (!strncmp (cptr, "C   ", 4))
chanMask |= 0x4;
else if (!strncmp (cptr, "LFE ", 4))
chanMask |= 0x8;
else
if (debug_logging_mode)
error_line ("undefined channel ID %c%c%c%c", cptr [0], cptr [1], cptr [2], cptr [3]);

cptr += 4;
}

if (debug_logging_mode)
error_line ("%d channels, mask = 0x%08x", numChannels, chanMask);
}
else if (!strncmp (dff_chunk_header.ckID, "CMPR", 4) && dff_chunk_header.ckDataSize >= 4) {
if (strncmp (cptr, "DSD ", 4)) {
error_line ("DSDIFF files must be uncompressed, not \"%c%c%c%c\"!",
cptr [0], cptr [1], cptr [2], cptr [3]);
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}

cptr += dff_chunk_header.ckDataSize;
}
else {
if (debug_logging_mode)
error_line ("got PROP/SND chunk type \"%c%c%c%c\" of %d bytes", dff_chunk_header.ckID [0],
dff_chunk_header.ckID [1], dff_chunk_header.ckID [2], dff_chunk_header.ckID [3], dff_chunk_header.ckDataSize);

cptr += dff_chunk_header.ckDataSize;
}
}
else {
error_line ("%s is not a valid .DFF file!", infilename);
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}
}

if (chanMask && (config->channel_mask || (config->qmode & QMODE_CHANS_UNASSIGNED))) {
error_line ("this DSDIFF file already has channel order information!");
free (prop_chunk);
return WAVPACK_SOFT_ERROR;
}
else if (chanMask)
config->channel_mask = chanMask;

config->bits_per_sample = 8;
config->bytes_per_sample = 1;
config->num_channels = numChannels;
config->sample_rate = sampleRate / 8;
config->qmode |= QMODE_DSD_MSB_FIRST;
}
else if (debug_logging_mode)
error_line ("got unknown PROP chunk type \"%c%c%c%c\" of %d bytes",
prop_chunk [0], prop_chunk [1], prop_chunk [2], prop_chunk [3], dff_chunk_header.ckDataSize);

free (prop_chunk);
}
else if (!strncmp (dff_chunk_header.ckID, "DSD ", 4)) {

            if (!config->num_channels) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}

total_samples = dff_chunk_header.ckDataSize / config->num_channels;
break;
}
else {          // just copy unknown chunks to output file

int bytes_to_copy = (int)(((dff_chunk_header.ckDataSize) + 1) & ~(int64_t)1);
char *buff;

if (bytes_to_copy < 0 || bytes_to_copy > 4194304) {
error_line ("%s is not a valid .DFF file!", infilename);
return WAVPACK_SOFT_ERROR;
}

buff = malloc (bytes_to_copy);

if (debug_logging_mode)
error_line ("extra unknown chunk \"%c%c%c%c\" of %d bytes",
dff_chunk_header.ckID [0], dff_chunk_header.ckID [1], dff_chunk_header.ckID [2],
dff_chunk_header.ckID [3], dff_chunk_header.ckDataSize);

if (!DoReadFile (infile, buff, bytes_to_copy, &bcount) ||
bcount != bytes_to_copy ||
(!(config->qmode & QMODE_NO_STORE_WRAPPER) &&
!WavpackAddWrapper (wpc, buff, bytes_to_copy))) {
error_line ("%s", WavpackGetErrorMessage (wpc));
free (buff);
return WAVPACK_SOFT_ERROR;
}

free (buff);
}
}

if (debug_logging_mode)
error_line ("setting configuration with %lld samples", total_samples);

if (!WavpackSetConfiguration64 (wpc, config, total_samples, NULL)) {
error_line ("%s: %s", infilename, WavpackGetErrorMessage (wpc));
return WAVPACK_SOFT_ERROR;
}

return WAVPACK_NO_ERROR;
}

MagickExport MagickBooleanType SetQuantumDepth(const Image *image,
QuantumInfo *quantum_info,const size_t depth)
{
size_t
extent,
quantum;

/*
Allocate the quantum pixel buffer.
*/
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(quantum_info != (QuantumInfo *) NULL);
assert(quantum_info->signature == MagickCoreSignature);
quantum_info->depth=depth;
if (quantum_info->format == FloatingPointQuantumFormat)
{
if (quantum_info->depth > 32)
quantum_info->depth=64;
else
if (quantum_info->depth > 16)
quantum_info->depth=32;
else
quantum_info->depth=16;
}
if (quantum_info->pixels != (unsigned char **) NULL)
DestroyQuantumPixels(quantum_info);
quantum=(quantum_info->pad+6)*(quantum_info->depth+7)/8;
  extent=image->columns*quantum;
  if ((image->columns != 0) && (quantum != (extent/image->columns)))
return(MagickFalse);
return(AcquireQuantumPixels(quantum_info,extent));
}

static EncodedJSValue JSC_HOST_CALL jsTestObjPrototypeFunctionOverloadedMethod4(ExecState* exec)
{
JSValue thisValue = exec->hostThisValue();
if (!thisValue.inherits(&JSTestObj::s_info))
return throwVMTypeError(exec);
JSTestObj* castedThis = jsCast<JSTestObj*>(asObject(thisValue));
ASSERT_GC_OBJECT_INHERITS(castedThis, &JSTestObj::s_info);
TestObj* impl = static_cast<TestObj*>(castedThis->impl());
if (exec->argumentCount() < 1)
        return throwVMError(exec, createTypeError(exec, "Not enough arguments"));
int intArg(MAYBE_MISSING_PARAMETER(exec, 0, DefaultIsUndefined).toInt32(exec));
if (exec->hadException())
return JSValue::encode(jsUndefined());
impl->overloadedMethod(intArg);
return JSValue::encode(jsUndefined());
}

int common_timer_set(struct k_itimer *timr, int flags,
struct itimerspec64 *new_setting,
struct itimerspec64 *old_setting)
{
const struct k_clock *kc = timr->kclock;
bool sigev_none;
ktime_t expires;

if (old_setting)
common_timer_get(timr, old_setting);

/* Prevent rearming by clearing the interval */
timr->it_interval = 0;
/*
* Careful here. On SMP systems the timer expiry function could be
* active and spinning on timr->it_lock.
*/
if (kc->timer_try_to_cancel(timr) < 0)
return TIMER_RETRY;

timr->it_active = 0;
timr->it_requeue_pending = (timr->it_requeue_pending + 2) &
~REQUEUE_PENDING;
timr->it_overrun_last = 0;

/* Switch off the timer when it_value is zero */
if (!new_setting->it_value.tv_sec && !new_setting->it_value.tv_nsec)
return 0;

timr->it_interval = timespec64_to_ktime(new_setting->it_interval);
expires = timespec64_to_ktime(new_setting->it_value);
	sigev_none = (timr->it_sigev_notify & ~SIGEV_THREAD_ID) == SIGEV_NONE;

kc->timer_arm(timr, expires, flags & TIMER_ABSTIME, sigev_none);
timr->it_active = !sigev_none;
return 0;
}

xsltNumberFormatGetAnyLevel(xsltTransformContextPtr context,
xmlNodePtr node,
xsltCompMatchPtr countPat,
xsltCompMatchPtr fromPat,
			    double *array,
			    xmlDocPtr doc,
			    xmlNodePtr elem)
{
int amount = 0;
int cnt = 0;
xmlNodePtr cur;

/* select the starting node */
switch (node->type) {
case XML_ELEMENT_NODE:
cur = node;
break;
case XML_ATTRIBUTE_NODE:
cur = ((xmlAttrPtr) node)->parent;
break;
case XML_TEXT_NODE:
case XML_PI_NODE:
case XML_COMMENT_NODE:
cur = node->parent;
break;
default:
cur = NULL;
break;
}

while (cur != NULL) {
/* process current node */
	if (countPat == NULL) {
	    if ((node->type == cur->type) &&
		/* FIXME: must use expanded-name instead of local name *
		xmlStrEqual(node->name, cur->name)) {
		    if ((node->ns == cur->ns) ||
		        ((node->ns != NULL) &&
			 (cur->ns != NULL) &&
		         (xmlStrEqual(node->ns->href,
		             cur->ns->href) )))
		        cnt++;
	    }
	} else {
	    if (xsltTestCompMatchList(context, cur, countPat))
		cnt++;
	}
if ((fromPat != NULL) &&
xsltTestCompMatchList(context, cur, fromPat)) {
break; /* while */
}

/* Skip to next preceding or ancestor */
if ((cur->type == XML_DOCUMENT_NODE) ||
#ifdef LIBXML_DOCB_ENABLED
(cur->type == XML_DOCB_DOCUMENT_NODE) ||
#endif
(cur->type == XML_HTML_DOCUMENT_NODE))
break; /* while */

while ((cur->prev != NULL) && ((cur->prev->type == XML_DTD_NODE) ||
(cur->prev->type == XML_XINCLUDE_START) ||
(cur->prev->type == XML_XINCLUDE_END)))
cur = cur->prev;
if (cur->prev != NULL) {
for (cur = cur->prev; cur->last != NULL; cur = cur->last);
} else {
cur = cur->parent;
}

}

array[amount++] = (double) cnt;

return(amount);
}

bool TypedUrlModelAssociator::AssociateModels() {
VLOG(1) << "Associating TypedUrl Models";
DCHECK(expected_loop_ == MessageLoop::current());

std::vector<history::URLRow> typed_urls;
if (!history_backend_->GetAllTypedURLs(&typed_urls)) {
LOG(ERROR) << "Could not get the typed_url entries.";
return false;
}

// Get all the visits.
std::map<history::URLID, history::VisitVector> visit_vectors;
for (std::vector<history::URLRow>::iterator ix = typed_urls.begin();
ix != typed_urls.end(); ++ix) {
if (!history_backend_->GetVisitsForURL(ix->id(),
&(visit_vectors[ix->id()]))) {
LOG(ERROR) << "Could not get the url's visits.";
return false;
}
// Sometimes (due to a bug elsewhere in the history or sync code, or due to
// a crash between adding a URL to the history database and updating the
// visit DB) the visit vector for a URL can be empty. If this happens, just
// create a new visit whose timestamp is the same as the last_visit time.
// This is a workaround for http://crbug.com/84258.
if (visit_vectors[ix->id()].empty()) {
history::VisitRow visit(
ix->id(), ix->last_visit(), 0, PageTransition::TYPED, 0);
visit_vectors[ix->id()].push_back(visit);
}
}

TypedUrlTitleVector titles;
TypedUrlVector new_urls;
TypedUrlVisitVector new_visits;
TypedUrlUpdateVector updated_urls;

{
sync_api::WriteTransaction trans(sync_service_->GetUserShare());
sync_api::ReadNode typed_url_root(&trans);
if (!typed_url_root.InitByTagLookup(kTypedUrlTag)) {
LOG(ERROR) << "Server did not create the top-level typed_url node. We "
<< "might be running against an out-of-date server.";
return false;
}

std::set<std::string> current_urls;
for (std::vector<history::URLRow>::iterator ix = typed_urls.begin();
ix != typed_urls.end(); ++ix) {
std::string tag = ix->url().spec();

history::VisitVector& visits = visit_vectors[ix->id()];

sync_api::ReadNode node(&trans);
if (node.InitByClientTagLookup(syncable::TYPED_URLS, tag)) {
// Same URL exists in sync data and in history data - compare the
// entries to see if there's any difference.
const sync_pb::TypedUrlSpecifics& typed_url(
node.GetTypedUrlSpecifics());
DCHECK_EQ(tag, typed_url.url());

// Initialize fields in |new_url| to the same values as the fields in
// the existing URLRow in the history DB. This is needed because we
// overwrite the existing value below in WriteToHistoryBackend(), but
// some of the values in that structure are not synced (like
// typed_count).
history::URLRow new_url(*ix);

std::vector<history::VisitInfo> added_visits;
int difference = MergeUrls(typed_url, *ix, &visits, &new_url,
&added_visits);
if (difference & DIFF_UPDATE_NODE) {
sync_api::WriteNode write_node(&trans);
if (!write_node.InitByClientTagLookup(syncable::TYPED_URLS, tag)) {
LOG(ERROR) << "Failed to edit typed_url sync node.";
return false;
}
// We don't want to resurrect old visits that have been aged out by
// other clients, so remove all visits that are older than the
// earliest existing visit in the sync node.
if (typed_url.visits_size() > 0) {
base::Time earliest_visit =
base::Time::FromInternalValue(typed_url.visits(0));
for (history::VisitVector::iterator it = visits.begin();
it != visits.end() && it->visit_time < earliest_visit; ) {
it = visits.erase(it);
}
// Should never be possible to delete all the items, since the
// visit vector contains all the items in typed_url.visits.
DCHECK(visits.size() > 0);
          } else {
            NOTREACHED() << "Syncing typed URL with no visits: " <<
                typed_url.url();
}
WriteToSyncNode(new_url, visits, &write_node);
}
if (difference & DIFF_LOCAL_TITLE_CHANGED) {
titles.push_back(std::pair<GURL, string16>(new_url.url(),
new_url.title()));
}
if (difference & DIFF_LOCAL_ROW_CHANGED) {
updated_urls.push_back(
std::pair<history::URLID, history::URLRow>(ix->id(), new_url));
}
if (difference & DIFF_LOCAL_VISITS_ADDED) {
new_visits.push_back(
std::pair<GURL, std::vector<history::VisitInfo> >(ix->url(),
added_visits));
}

Associate(&tag, node.GetId());
} else {
// Sync has never seen this URL before.
sync_api::WriteNode node(&trans);
if (!node.InitUniqueByCreation(syncable::TYPED_URLS,
typed_url_root, tag)) {
LOG(ERROR) << "Failed to create typed_url sync node.";
return false;
}

node.SetTitle(UTF8ToWide(tag));
WriteToSyncNode(*ix, visits, &node);

Associate(&tag, node.GetId());
}

current_urls.insert(tag);
}

// Now walk the sync nodes and detect any URLs that exist there, but not in
// the history DB, so we can add them to our local history DB.
int64 sync_child_id = typed_url_root.GetFirstChildId();
while (sync_child_id != sync_api::kInvalidId) {
sync_api::ReadNode sync_child_node(&trans);
if (!sync_child_node.InitByIdLookup(sync_child_id)) {
LOG(ERROR) << "Failed to fetch child node.";
return false;
}
const sync_pb::TypedUrlSpecifics& typed_url(
sync_child_node.GetTypedUrlSpecifics());

if (current_urls.find(typed_url.url()) == current_urls.end()) {
new_visits.push_back(
std::pair<GURL, std::vector<history::VisitInfo> >(
GURL(typed_url.url()),
std::vector<history::VisitInfo>()));
std::vector<history::VisitInfo>& visits = new_visits.back().second;
history::URLRow new_url(GURL(typed_url.url()));
TypedUrlModelAssociator::UpdateURLRowFromTypedUrlSpecifics(
typed_url, &new_url);

for (int c = 0; c < typed_url.visits_size(); ++c) {
DCHECK(c == 0 || typed_url.visits(c) > typed_url.visits(c - 1));
DCHECK_LE(typed_url.visit_transitions(c),
static_cast<int>(PageTransition::LAST_CORE));
visits.push_back(history::VisitInfo(
base::Time::FromInternalValue(typed_url.visits(c)),
static_cast<PageTransition::Type>(
typed_url.visit_transitions(c))));
}

Associate(&typed_url.url(), sync_child_node.GetId());
new_urls.push_back(new_url);
}
      sync_child_id = sync_child_node.GetSuccessorId();
}
}

// Since we're on the history thread, we don't have to worry about updating
// the history database after closing the write transaction, since
// this is the only thread that writes to the database.  We also don't have
// to worry about the sync model getting out of sync, because changes are
// propagated to the ChangeProcessor on this thread.
return WriteToHistoryBackend(&titles, &new_urls, &updated_urls,
&new_visits, NULL);
}

