status_t GraphicBuffer::unflatten(
void const*& buffer, size_t& size, int const*& fds, size_t& count) {
if (size < 8*sizeof(int)) return NO_MEMORY;

int const* buf = static_cast<int const*>(buffer);
if (buf[0] != 'GBFR') return BAD_TYPE;


const size_t numFds  = buf[8];
const size_t numInts = buf[9];

const size_t sizeNeeded = (10 + numInts) * sizeof(int);
if (size < sizeNeeded) return NO_MEMORY;

    size_t fdCountNeeded = 0;
if (count < fdCountNeeded) return NO_MEMORY;

if (handle) {
// free previous handle if any
free_handle();
}

if (numFds || numInts) {
width  = buf[1];
height = buf[2];
stride = buf[3];

format = buf[4];
usage  = buf[5];
native_handle* h = native_handle_create(numFds, numInts);
memcpy(h->data,          fds,     numFds*sizeof(int));
memcpy(h->data + numFds, &buf[10], numInts*sizeof(int));
handle = h;
} else {
width = height = stride = format = usage = 0;
handle = NULL;
}

mId = static_cast<uint64_t>(buf[6]) << 32;
mId |= static_cast<uint32_t>(buf[7]);

mOwner = ownHandle;

if (handle != 0) {
status_t err = mBufferMapper.registerBuffer(handle);
if (err != NO_ERROR) {
width = height = stride = format = usage = 0;
handle = NULL;
ALOGE("unflatten: registerBuffer failed: %s (%d)",
strerror(-err), err);
return err;
}
}

buffer = reinterpret_cast<void const*>(static_cast<int const*>(buffer) + sizeNeeded);
size -= sizeNeeded;
fds += numFds;
count -= numFds;

return NO_ERROR;
}

long long mkvparser::ReadUInt(IMkvReader* pReader, long long pos, long& len)
{
    assert(pReader);
    assert(pos >= 0);

    int status;

#ifdef _DEBUG
    long long total, available;
    status = pReader->Length(&total, &available);
    assert(status >= 0);
    assert((total < 0) || (available <= total));
    assert(pos < available);
    assert((available - pos) >= 1);  //assume here max u-int len is 8
#endif

    len = 1;

    unsigned char b;

status = pReader->Read(pos, 1, &b);

    if (status < 0)  //error or underflow
        return status;
    if (status > 0)  //interpreted as "underflow"
        return E_BUFFER_NOT_FULL;
    if (b == 0)  //we can't handle u-int values larger than 8 bytes
        return E_FILE_FORMAT_INVALID;
    unsigned char m = 0x80;
    while (!(b & m))
    {
        m >>= 1;
        ++len;
}

#ifdef _DEBUG
    assert((available - pos) >= len);
#endif

    long long result = b & (~m);
++pos;

    for (int i = 1; i < len; ++i)
    {
        status = pReader->Read(pos, 1, &b);
        if (status < 0)
        {
            len = 1;
            return status;
        }
        if (status > 0)
        {
            len = 1;
            return E_BUFFER_NOT_FULL;
        }
        result <<= 8;
        result |= b;
        ++pos;
    }
    return result;
}

static int jpc_qcd_dumpparms(jpc_ms_t *ms, FILE *out)
{
jpc_qcd_t *qcd = &ms->parms.qcd;
int i;
fprintf(out, "qntsty = %d; numguard = %d; numstepsizes = %d\n",
(int) qcd->compparms.qntsty, qcd->compparms.numguard, qcd->compparms.numstepsizes);
for (i = 0; i < qcd->compparms.numstepsizes; ++i) {
fprintf(out, "expn[%d] = 0x%04x; mant[%d] = 0x%04x;\n",
		  i, (unsigned) JPC_QCX_GETEXPN(qcd->compparms.stepsizes[i]),
		  i, (unsigned) JPC_QCX_GETMANT(qcd->compparms.stepsizes[i]));
}
return 0;
}

void ExtensionWebContentsObserver::RenderViewCreated(
content::RenderViewHost* render_view_host) {
// TODO(devlin): Most/all of this should move to RenderFrameCreated.
const Extension* extension = GetExtension(render_view_host);
if (!extension)
return;

  content::RenderProcessHost* process = render_view_host->GetProcess();
  // Some extensions use chrome:// URLs.
  // This is a temporary solution. Replace it with access to chrome-static:
  // once it is implemented. See: crbug.com/226927.
Manifest::Type type = extension->GetType();
  if (type == Manifest::TYPE_EXTENSION ||
      type == Manifest::TYPE_LEGACY_PACKAGED_APP ||
      (type == Manifest::TYPE_PLATFORM_APP &&
       extension->location() == Manifest::COMPONENT)) {
    content::ChildProcessSecurityPolicy::GetInstance()->GrantScheme(
        process->GetID(), content::kChromeUIScheme);
  }

// Some extensions use file:// URLs.
if (type == Manifest::TYPE_EXTENSION ||
type == Manifest::TYPE_LEGACY_PACKAGED_APP) {
ExtensionPrefs* prefs = ExtensionPrefs::Get(browser_context_);
if (prefs->AllowFileAccess(extension->id())) {
content::ChildProcessSecurityPolicy::GetInstance()->GrantScheme(
          process->GetID(), url::kFileScheme);
}
}

// Tells the new view that it's hosted in an extension process.
//
// This will often be a rendant IPC, because activating extensions happens at
// the process level, not at the view level. However, without some mild
// refactoring this isn't trivial to do, and this way is simpler.
//
// Plus, we can delete the concept of activating an extension once site
// isolation is turned on.
render_view_host->Send(new ExtensionMsg_ActivateExtension(extension->id()));
}

