int sbusfb_ioctl_helper(unsigned long cmd, unsigned long arg,
struct fb_info *info,
int type, int fb_depth, unsigned long fb_size)
{
switch(cmd) {
case FBIOGTYPE: {
struct fbtype __user *f = (struct fbtype __user *) arg;

if (put_user(type, &f->fb_type) ||
__put_user(info->var.yres, &f->fb_height) ||
__put_user(info->var.xres, &f->fb_width) ||
__put_user(fb_depth, &f->fb_depth) ||
__put_user(0, &f->fb_cmsize) ||
__put_user(fb_size, &f->fb_cmsize))
return -EFAULT;
return 0;
}
case FBIOPUTCMAP_SPARC: {
struct fbcmap __user *c = (struct fbcmap __user *) arg;
struct fb_cmap cmap;
u16 red, green, blue;
u8 red8, green8, blue8;
unsigned char __user *ured;
unsigned char __user *ugreen;
unsigned char __user *ublue;
		int index, count, i;

if (get_user(index, &c->index) ||
__get_user(count, &c->count) ||
__get_user(ured, &c->red) ||
__get_user(ugreen, &c->green) ||
__get_user(ublue, &c->blue))
return -EFAULT;

cmap.len = 1;
cmap.red = &red;
cmap.green = &green;
cmap.blue = &blue;
cmap.transp = NULL;
for (i = 0; i < count; i++) {
int err;

if (get_user(red8, &ured[i]) ||
get_user(green8, &ugreen[i]) ||
get_user(blue8, &ublue[i]))
return -EFAULT;

red = red8 << 8;
green = green8 << 8;
blue = blue8 << 8;

cmap.start = index + i;
err = fb_set_cmap(&cmap, info);
if (err)
return err;
}
return 0;
}
case FBIOGETCMAP_SPARC: {
struct fbcmap __user *c = (struct fbcmap __user *) arg;
unsigned char __user *ured;
unsigned char __user *ugreen;
unsigned char __user *ublue;
struct fb_cmap *cmap = &info->cmap;
		int index, count, i;
u8 red, green, blue;

if (get_user(index, &c->index) ||
__get_user(count, &c->count) ||
__get_user(ured, &c->red) ||
__get_user(ugreen, &c->green) ||
__get_user(ublue, &c->blue))
return -EFAULT;

if (index + count > cmap->len)
return -EINVAL;

for (i = 0; i < count; i++) {
red = cmap->red[index + i] >> 8;
green = cmap->green[index + i] >> 8;
blue = cmap->blue[index + i] >> 8;
if (put_user(red, &ured[i]) ||
put_user(green, &ugreen[i]) ||
put_user(blue, &ublue[i]))
return -EFAULT;
}
return 0;
}
default:
return -EINVAL;
}
}

PersistentHistogramAllocator::GetCreateHistogramResultHistogram() {
  // A value that can be stored in an AtomicWord as a flag. It must not be zero
  // or a valid address.
  constexpr subtle::AtomicWord kHistogramUnderConstruction = 1;
  // This is a similar to LazyInstance but with return-if-under-construction
  // rather than yielding the CPU until construction completes. This is
  // necessary because the FactoryGet() below creates a histogram and thus
  // recursively calls this method to try to store the result.
  // Get the existing pointer. If the "under construction" flag is present,
  // abort now. It's okay to return null from this method.
  static subtle::AtomicWord atomic_histogram_pointer = 0;
  subtle::AtomicWord histogram_value =
      subtle::Acquire_Load(&atomic_histogram_pointer);
  if (histogram_value == kHistogramUnderConstruction)
    return nullptr;
  // If a valid histogram pointer already exists, return it.
  if (histogram_value)
    return reinterpret_cast<HistogramBase*>(histogram_value);
  // Set the "under construction" flag; abort if something has changed.
  if (subtle::NoBarrier_CompareAndSwap(&atomic_histogram_pointer, 0,
                                       kHistogramUnderConstruction) != 0) {
    return nullptr;
  }
  // Only one thread can be here. Even recursion will be thwarted above.
  if (GlobalHistogramAllocator::Get()) {
    DVLOG(1) << "Creating the results-histogram inside persistent"
             << " memory can cause future allocations to crash if"
             << " that memory is ever released (for testing).";
  }
  HistogramBase* histogram_pointer = LinearHistogram::FactoryGet(
      kResultHistogram, 1, CREATE_HISTOGRAM_MAX, CREATE_HISTOGRAM_MAX + 1,
      HistogramBase::kUmaTargetedHistogramFlag);
  subtle::Release_Store(
      &atomic_histogram_pointer,
      reinterpret_cast<subtle::AtomicWord>(histogram_pointer));
  return histogram_pointer;
}

int32 CommandBufferProxyImpl::CreateTransferBuffer(
size_t size, int32 id_request) {
if (last_state_.error != gpu::error::kNoError)
return -1;

// Take ownership of shared memory. This will close the handle if Send below
// fails. Otherwise, callee takes ownership before this variable
// goes out of scope by duping the handle.
scoped_ptr<base::SharedMemory> shm(
channel_->factory()->AllocateSharedMemory(size));
if (!shm.get())
return -1;

base::SharedMemoryHandle handle = shm->handle();
#if defined(OS_POSIX)
DCHECK(!handle.auto_close);
#endif

int32 id;
if (!Send(new GpuCommandBufferMsg_RegisterTransferBuffer(route_id_,
handle,
size,
id_request,
&id))) {
return -1;
}

return id;
}

ProcessTCPHeader(tTcpIpPacketParsingResult _res, PVOID pIpHeader, ULONG len, USHORT ipHeaderSize)
{
ULONG tcpipDataAt;
tTcpIpPacketParsingResult res = _res;
tcpipDataAt = ipHeaderSize + sizeof(TCPHeader);
    res.xxpStatus = ppresXxpIncomplete;
res.TcpUdp = ppresIsTCP;

if (len >= tcpipDataAt)
{
TCPHeader *pTcpHeader = (TCPHeader *)RtlOffsetToPointer(pIpHeader, ipHeaderSize);
res.xxpStatus = ppresXxpKnown;
tcpipDataAt = ipHeaderSize + TCP_HEADER_LENGTH(pTcpHeader);
res.XxpIpHeaderSize = tcpipDataAt;
}
else
{
DPrintf(2, ("tcp: %d < min headers %d\n", len, tcpipDataAt));
}
return res;
}

