void RunTestsInFile(const std::string& filename,
const std::string& pdf_filename) {
extensions::ResultCatcher catcher;

GURL url(embedded_test_server()->GetURL("/pdf/" + pdf_filename));

// It should be good enough to just navigate to the URL. But loading up the
// BrowserPluginGuest seems to happen asynchronously as there was flakiness
// being seen due to the BrowserPluginGuest not being available yet (see
// crbug.com/498077). So instead use |LoadPdf| which ensures that the PDF is
// loaded before continuing.
    ASSERT_TRUE(LoadPdf(url));
    content::WebContents* contents =
        browser()->tab_strip_model()->GetActiveWebContents();
    content::BrowserPluginGuestManager* guest_manager =
        contents->GetBrowserContext()->GetGuestManager();
    content::WebContents* guest_contents =
        guest_manager->GetFullPageGuest(contents);
ASSERT_TRUE(guest_contents);

base::FilePath test_data_dir;
PathService::Get(chrome::DIR_TEST_DATA, &test_data_dir);
test_data_dir = test_data_dir.Append(FILE_PATH_LITERAL("pdf"));
base::FilePath test_util_path = test_data_dir.AppendASCII("test_util.js");
std::string test_util_js;
ASSERT_TRUE(base::ReadFileToString(test_util_path, &test_util_js));

base::FilePath test_file_path = test_data_dir.AppendASCII(filename);
std::string test_js;
ASSERT_TRUE(base::ReadFileToString(test_file_path, &test_js));

test_util_js.append(test_js);
ASSERT_TRUE(content::ExecuteScript(guest_contents, test_util_js));

if (!catcher.GetNextResult())
FAIL() << catcher.message();
}

int _dbus_printf_string_upper_bound (const char *format,
va_list args)
{
/* MSVCRT's vsnprintf semantics are a bit different */
char buf[1024];
int bufsize;
int len;

bufsize = sizeof (buf);
  len = _vsnprintf (buf, bufsize - 1, format, args);

while (len == -1) /* try again */
{

p = malloc (bufsize);

if (p == NULL)
return -1;

if (p == NULL)
return -1;

      len = _vsnprintf (p, bufsize - 1, format, args);
free (p);
}
* Returns the UTF-16 form of a UTF-8 string. The result should be
* freed with dbus_free() when no longer needed.
*
* @param str the UTF-8 string
* @param error return location for error code
*/
wchar_t *
_dbus_win_utf8_to_utf16 (const char *str,
DBusError  *error)
{
DBusString s;
int n;
wchar_t *retval;

_dbus_string_init_const (&s, str);

if (!_dbus_string_validate_utf8 (&s, 0, _dbus_string_get_length (&s)))
{
dbus_set_error_const (error, DBUS_ERROR_FAILED, "Invalid UTF-8");
return NULL;
}

n = MultiByteToWideChar (CP_UTF8, 0, str, -1, NULL, 0);

if (n == 0)
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
return NULL;
}

retval = dbus_new (wchar_t, n);

if (!retval)
{
_DBUS_SET_OOM (error);
return NULL;
}

if (MultiByteToWideChar (CP_UTF8, 0, str, -1, retval, n) != n)
{
dbus_free (retval);
dbus_set_error_const (error, DBUS_ERROR_FAILED, "MultiByteToWideChar inconsistency");
return NULL;
}

return retval;
}

/**
* Returns the UTF-8 form of a UTF-16 string. The result should be
* freed with dbus_free() when no longer needed.
*
* @param str the UTF-16 string
* @param error return location for error code
*/
char *
_dbus_win_utf16_to_utf8 (const wchar_t *str,
DBusError     *error)
{
int n;
char *retval;

n = WideCharToMultiByte (CP_UTF8, 0, str, -1, NULL, 0, NULL, NULL);

if (n == 0)
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
return NULL;
}

retval = dbus_malloc (n);

if (!retval)
{
_DBUS_SET_OOM (error);
return NULL;
}

if (WideCharToMultiByte (CP_UTF8, 0, str, -1, retval, n, NULL, NULL) != n)
{
dbus_free (retval);
dbus_set_error_const (error, DBUS_ERROR_FAILED, "WideCharToMultiByte inconsistency");
return NULL;
}

return retval;
}






