int dev_forward_skb(struct net_device *dev, struct sk_buff *skb)
{
skb_orphan(skb);

	if (!(dev->flags & IFF_UP))
		return NET_RX_DROP;
	if (skb->len > (dev->mtu + dev->hard_header_len))
return NET_RX_DROP;
skb_set_dev(skb, dev);
skb->tstamp.tv64 = 0;
skb->pkt_type = PACKET_HOST;
skb->protocol = eth_type_trans(skb, dev);
return netif_rx(skb);
}

void SocketStream::Connect() {
DCHECK(base::MessageLoop::current())
<< "The current base::MessageLoop must exist";
DCHECK_EQ(base::MessageLoop::TYPE_IO, base::MessageLoop::current()->type())
<< "The current base::MessageLoop must be TYPE_IO";
  if (context_.get()) {
context_->ssl_config_service()->GetSSLConfig(&server_ssl_config_);
proxy_ssl_config_ = server_ssl_config_;
}
CheckPrivacyMode();

DCHECK_EQ(next_state_, STATE_NONE);

AddRef();  // Released in Finish()
// Open a connection asynchronously, so that delegate won't be called
// back before returning Connect().
next_state_ = STATE_BEFORE_CONNECT;
net_log_.BeginEvent(
NetLog::TYPE_SOCKET_STREAM_CONNECT,
NetLog::StringCallback("url", &url_.possibly_invalid_spec()));
base::MessageLoop::current()->PostTask(
FROM_HERE, base::Bind(&SocketStream::DoLoop, this, OK));
}

static int get_default_root(pool *p, int allow_symlinks, const char **root) {
config_rec *c = NULL;
const char *dir = NULL;
int res;

c = find_config(main_server->conf, CONF_PARAM, "DefaultRoot", FALSE);
while (c != NULL) {
pr_signals_handle();

/* Check the groups acl */
if (c->argc < 2) {
dir = c->argv[0];
break;
}

res = pr_expr_eval_group_and(((char **) c->argv)+1);
if (res) {
dir = c->argv[0];
break;
}

c = find_config_next(c, c->next, CONF_PARAM, "DefaultRoot", FALSE);
}

if (dir != NULL) {
const char *new_dir;

/* Check for any expandable variables. */
new_dir = path_subst_uservar(p, &dir);
if (new_dir != NULL) {
dir = new_dir;
}

if (strncmp(dir, "/", 2) == 0) {
dir = NULL;

} else {
char *realdir;
int xerrno = 0;

if (allow_symlinks == FALSE) {
char *path, target_path[PR_TUNABLE_PATH_MAX + 1];
        struct stat st;
size_t pathlen;

/* First, deal with any possible interpolation.  dir_realpath() will
* do this for us, but dir_realpath() ALSO automatically follows
* symlinks, which is what we do NOT want to do here.
*/

path = pstrdup(p, dir);
if (*path != '/') {
if (*path == '~') {
if (pr_fs_interpolate(dir, target_path,
sizeof(target_path)-1) < 0) {
return -1;
}

path = target_path;
}
}

/* Note: lstat(2) is sensitive to the presence of a trailing slash on
* the path, particularly in the case of a symlink to a directory.
* Thus to get the correct test, we need to remove any trailing slash
* that might be present.  Subtle.
*/
pathlen = strlen(path);
if (pathlen > 1 &&
path[pathlen-1] == '/') {
path[pathlen-1] = '\0';
}

        pr_fs_clear_cache2(path);
        res = pr_fsio_lstat(path, &st);
if (res < 0) {
          xerrno = errno;
          pr_log_pri(PR_LOG_WARNING, "error: unable to check %s: %s", path,
            strerror(xerrno));
          errno = xerrno;
          return -1;
        }

        if (S_ISLNK(st.st_mode)) {
          pr_log_pri(PR_LOG_WARNING,
            "error: DefaultRoot %s is a symlink (denied by AllowChrootSymlinks "
            "config)", path);
errno = EPERM;
return -1;
}
}

/* We need to be the final user here so that if the user has their home
* directory with a mode the user proftpd is running (i.e. the User
* directive) as can not traverse down, we can still have the default
* root.
*/

pr_fs_clear_cache2(dir);

PRIVS_USER
realdir = dir_realpath(p, dir);
xerrno = errno;
PRIVS_RELINQUISH

if (realdir) {
dir = realdir;

} else {
/* Try to provide a more informative message. */
char interp_dir[PR_TUNABLE_PATH_MAX + 1];

memset(interp_dir, '\0', sizeof(interp_dir));
(void) pr_fs_interpolate(dir, interp_dir, sizeof(interp_dir)-1);

pr_log_pri(PR_LOG_NOTICE,
"notice: unable to use DefaultRoot '%s' [resolved to '%s']: %s",
dir, interp_dir, strerror(xerrno));

errno = xerrno;
}
}
}

*root = dir;
return 0;
}

dump_keywords(vector_t *keydump, int level, FILE *fp)
{
unsigned int i;
keyword_t *keyword_vec;
	char file_name[21];

if (!level) {
snprintf(file_name, sizeof(file_name), "/tmp/keywords.%d", getpid());
		fp = fopen(file_name, "w");
if (!fp)
return;
}

for (i = 0; i < vector_size(keydump); i++) {
keyword_vec = vector_slot(keydump, i);
fprintf(fp, "%*sKeyword : %s (%s)\n", level * 2, "", keyword_vec->string, keyword_vec->active ? "active": "disabled");
if (keyword_vec->sub)
dump_keywords(keyword_vec->sub, level + 1, fp);
}

if (!level)
fclose(fp);
}

status_t BnHDCP::onTransact(
uint32_t code, const Parcel &data, Parcel *reply, uint32_t flags) {
switch (code) {
case HDCP_SET_OBSERVER:
{
CHECK_INTERFACE(IHDCP, data, reply);

sp<IHDCPObserver> observer =
interface_cast<IHDCPObserver>(data.readStrongBinder());

reply->writeInt32(setObserver(observer));
return OK;
}

case HDCP_INIT_ASYNC:
{
CHECK_INTERFACE(IHDCP, data, reply);

const char *host = data.readCString();
unsigned port = data.readInt32();

reply->writeInt32(initAsync(host, port));
return OK;
}

case HDCP_SHUTDOWN_ASYNC:
{
CHECK_INTERFACE(IHDCP, data, reply);

reply->writeInt32(shutdownAsync());
return OK;
}

case HDCP_GET_CAPS:
{
CHECK_INTERFACE(IHDCP, data, reply);

reply->writeInt32(getCaps());
return OK;
}


case HDCP_ENCRYPT:
{
size_t size = data.readInt32();

            void *inData = malloc(2 * size);
void *outData = (uint8_t *)inData + size;

data.read(inData, size);

uint32_t streamCTR = data.readInt32();
uint64_t inputCTR;
status_t err = encrypt(inData, size, streamCTR, &inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->writeInt64(inputCTR);
reply->write(outData, size);
}

free(inData);
inData = outData = NULL;

return OK;
}

case HDCP_ENCRYPT_NATIVE:
{
CHECK_INTERFACE(IHDCP, data, reply);

sp<GraphicBuffer> graphicBuffer = new GraphicBuffer();
data.read(*graphicBuffer);
size_t offset = data.readInt32();
size_t size = data.readInt32();
uint32_t streamCTR = data.readInt32();
void *outData = malloc(size);
uint64_t inputCTR;

status_t err = encryptNative(graphicBuffer, offset, size,
streamCTR, &inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->writeInt64(inputCTR);
reply->write(outData, size);
}

free(outData);
outData = NULL;

return OK;
}


case HDCP_DECRYPT:
{
size_t size = data.readInt32();

            void *inData = malloc(2 * size);
void *outData = (uint8_t *)inData + size;

data.read(inData, size);

uint32_t streamCTR = data.readInt32();
uint64_t inputCTR = data.readInt64();
status_t err = decrypt(inData, size, streamCTR, inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->write(outData, size);
}

free(inData);
inData = outData = NULL;

return OK;
}

default:
return BBinder::onTransact(code, data, reply, flags);
}
}

