void UsbDeviceImpl::OnPathAccessRequestComplete(const OpenCallback& callback,
                                                bool success) {
  if (success) {
    blocking_task_runner_->PostTask(
        FROM_HERE,
        base::Bind(&UsbDeviceImpl::OpenOnBlockingThread, this, callback));
  } else {
    // Once permission_broker changes for crbug.com/496469 land,
    // RequestPathAccess will fail for partially claimed devices regardless of
    // the interface number requested. Fall back to OpenPath to prevent a
    // regression. This code will then be removed.
    chromeos::PermissionBrokerClient* client =
        chromeos::DBusThreadManager::Get()->GetPermissionBrokerClient();
    DCHECK(client) << "Could not get permission broker client.";
    client->OpenPath(
        device_path_,
        base::Bind(&UsbDeviceImpl::OnOpenRequestComplete, this, callback));
  }
}

status_t MediaHTTP::connect(
const char *uri,
const KeyedVector<String8, String8> *headers,
off64_t /* offset */) {
if (mInitCheck != OK) {
return mInitCheck;
}

KeyedVector<String8, String8> extHeaders;
if (headers != NULL) {
extHeaders = *headers;
}

if (extHeaders.indexOfKey(String8("User-Agent")) < 0) {

extHeaders.add(String8("User-Agent"), String8(MakeUserAgent().c_str()));
}

    bool success = mHTTPConnection->connect(uri, &extHeaders);

mLastHeaders = extHeaders;
    mLastURI = uri;

mCachedSizeValid = false;

if (success) {
        AString sanitized = uriDebugString(uri);
mName = String8::format("MediaHTTP(%s)", sanitized.c_str());
}

return success ? OK : UNKNOWN_ERROR;
}

void SessionChangeProcessor::ApplyChangesFromSyncModel(
const sync_api::BaseTransaction* trans,
const sync_api::ImmutableChangeRecordList& changes) {
DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI));
if (!running()) {
return;
}

StopObserving();

sync_api::ReadNode root(trans);
if (!root.InitByTagLookup(kSessionsTag)) {
error_handler()->OnUnrecoverableError(FROM_HERE,
"Sessions root node lookup failed.");
return;
}

for (sync_api::ChangeRecordList::const_iterator it =
changes.Get().begin(); it != changes.Get().end(); ++it) {
const sync_api::ChangeRecord& change = *it;
sync_api::ChangeRecord::Action action(change.action);
if (sync_api::ChangeRecord::ACTION_DELETE == action) {
// Deletions should only be for a foreign client itself, and hence affect
// the header node, never a tab node.
sync_api::ReadNode node(trans);
if (!node.InitByIdLookup(change.id)) {
error_handler()->OnUnrecoverableError(FROM_HERE,
"Session node lookup failed.");
return;
}
DCHECK_EQ(node.GetModelType(), syncable::SESSIONS);
const sync_pb::SessionSpecifics& specifics = node.GetSessionSpecifics();
session_model_associator_->DisassociateForeignSession(
specifics.session_tag());
continue;
}

// Handle an update or add.
sync_api::ReadNode sync_node(trans);
if (!sync_node.InitByIdLookup(change.id)) {
error_handler()->OnUnrecoverableError(FROM_HERE,
"Session node lookup failed.");
return;
}

// Check that the changed node is a child of the session folder.
DCHECK(root.GetId() == sync_node.GetParentId());
DCHECK(syncable::SESSIONS == sync_node.GetModelType());

const sync_pb::SessionSpecifics& specifics(
sync_node.GetSessionSpecifics());
if (specifics.session_tag() ==
session_model_associator_->GetCurrentMachineTag() &&
!setup_for_test_) {
// We should only ever receive a change to our own machine's session info
// if encryption was turned on. In that case, the data is still the same,
// so we can ignore.
LOG(WARNING) << "Dropping modification to local session.";
StartObserving();
return;
}
    const base::Time& mtime = sync_node.GetModificationTime();
// Model associator handles foreign session update and add the same.
session_model_associator_->AssociateForeignSpecifics(specifics, mtime);
}

// Notify foreign session handlers that there are new sessions.
NotificationService::current()->Notify(
chrome::NOTIFICATION_FOREIGN_SESSION_UPDATED,
NotificationService::AllSources(),
NotificationService::NoDetails());

StartObserving();
}

