// with |this| which is already freed.
//
// if (ibus_) {
//   g_signal_handlers_disconnect_by_func(
//       ibus_,
//       reinterpret_cast<gpointer>(
//           G_CALLBACK(IBusBusConnectedCallback)),
//       this);
//   ...
// }
// if (ibus_panel_service_) {
