UserSelectionScreen::UpdateAndReturnUserListForWebUI() {
std::unique_ptr<base::ListValue> users_list =
std::make_unique<base::ListValue>();

// TODO(nkostylev): Move to a separate method in UserManager.
// http://crbug.com/230852
const AccountId owner = GetOwnerAccountId();
const bool is_signin_to_add = IsSigninToAdd();

users_to_send_ = PrepareUserListForSending(users_, owner, is_signin_to_add);

user_auth_type_map_.clear();

  for (user_manager::UserList::const_iterator it = users_to_send_.begin();
       it != users_to_send_.end(); ++it) {
    const AccountId& account_id = (*it)->GetAccountId();
bool is_owner = (account_id == owner);
const bool is_public_account =
        ((*it)->GetType() == user_manager::USER_TYPE_PUBLIC_ACCOUNT);
const proximity_auth::mojom::AuthType initial_auth_type =
is_public_account
? proximity_auth::mojom::AuthType::EXPAND_THEN_USER_CLICK
            : (ShouldForceOnlineSignIn(*it)
? proximity_auth::mojom::AuthType::ONLINE_SIGN_IN
: proximity_auth::mojom::AuthType::OFFLINE_PASSWORD);
user_auth_type_map_[account_id] = initial_auth_type;

auto user_dict = std::make_unique<base::DictionaryValue>();
const std::vector<std::string>* public_session_recommended_locales =
public_session_recommended_locales_.find(account_id) ==
public_session_recommended_locales_.end()
? nullptr
: &public_session_recommended_locales_[account_id];
    FillUserDictionary(*it, is_owner, is_signin_to_add, initial_auth_type,
public_session_recommended_locales, user_dict.get());
    user_dict->SetBoolean(kKeyCanRemove, CanRemoveUser(*it));
users_list->Append(std::move(user_dict));
}

return users_list;
}

void pdf_load_pages_kids(FILE *fp, pdf_t *pdf)
{
int     i, id, dummy;
char   *buf, *c;
long    start, sz;

start = ftell(fp);

/* Load all kids for all xref tables (versions) */
for (i=0; i<pdf->n_xrefs; i++)
{
if (pdf->xrefs[i].version && (pdf->xrefs[i].end != 0))
{
fseek(fp, pdf->xrefs[i].start, SEEK_SET);
while (SAFE_F(fp, (fgetc(fp) != 't')))
; /* Iterate to trailer */

/* Get root catalog */
sz = pdf->xrefs[i].end - ftell(fp);
            buf = malloc(sz + 1);
SAFE_E(fread(buf, 1, sz, fp), sz, "Failed to load /Root.\n");
buf[sz] = '\0';
if (!(c = strstr(buf, "/Root")))
{
free(buf);
continue;
}

/* Jump to catalog (root) */
id = atoi(c + strlen("/Root") + 1);
free(buf);
buf = get_object(fp, id, &pdf->xrefs[i], NULL, &dummy);
if (!buf || !(c = strstr(buf, "/Pages")))
{
free(buf);
continue;
}

/* Start at the first Pages obj and get kids */
id = atoi(c + strlen("/Pages") + 1);
load_kids(fp, id, &pdf->xrefs[i]);
free(buf);
}
}

fseek(fp, start, SEEK_SET);
}

 void EventReaderLibevdevCros::OnFileCanReadWithoutBlocking(int fd) {
   if (EvdevRead(&evdev_)) {
     if (errno == EINTR || errno == EAGAIN)
       return;
    if (errno != ENODEV)
      PLOG(ERROR) << "error reading device " << path_.value();
    Stop();
    return;
  }
}

int BrowserMainLoop::PreCreateThreads() {
// SequencedWorkerPool shouldn't be enabled yet. It should be enabled below by
// either |parts_|->PreCreateThreads() or
// base::SequencedWorkerPool::EnableForProcess().
// TODO(fdoray): Uncomment this line.
// DCHECK(!base::SequencedWorkerPool::IsEnabled());

if (parts_) {
TRACE_EVENT0("startup",
"BrowserMainLoop::CreateThreads:PreCreateThreads");

result_code_ = parts_->PreCreateThreads();
}

// Enable SequencedWorkerPool if |parts_|->PreCreateThreads() hasn't enabled
// it.
// TODO(fdoray): Remove this once the SequencedWorkerPool to TaskScheduler
// redirection experiment concludes https://crbug.com/622400.
if (!base::SequencedWorkerPool::IsEnabled())
base::SequencedWorkerPool::EnableForProcess();

const base::CommandLine* command_line =
base::CommandLine::ForCurrentProcess();
// Note that we do not initialize a new FeatureList when calling this for
// the second time.
base::FeatureList::InitializeInstance(
command_line->GetSwitchValueASCII(switches::kEnableFeatures),
