PassOwnPtr<WebCore::GraphicsContext> LayerTreeCoordinator::beginContentUpdate(const WebCore::IntSize& size, ShareableBitmap::Flags flags, ShareableSurface::Handle& handle, WebCore::IntPoint& offset)
{
    OwnPtr<WebCore::GraphicsContext> graphicsContext;
    for (unsigned i = 0; i < m_updateAtlases.size(); ++i) {
        UpdateAtlas* atlas = m_updateAtlases[i].get();
        if (atlas->flags() == flags) {
            graphicsContext = atlas->beginPaintingOnAvailableBuffer(handle, size, offset);
            if (graphicsContext)
                return graphicsContext.release();
        }
    }

     static const int ScratchBufferDimension = 1024; // Should be a power of two.
     m_updateAtlases.append(adoptPtr(new UpdateAtlas(ScratchBufferDimension, flags)));
     return m_updateAtlases.last()->beginPaintingOnAvailableBuffer(handle, size, offset);
 }

void TabletModeWindowState::LeaveTabletMode(wm::WindowState* window_state) {
  // Only do bounds change animation if the window is the top window or a window
  // showing in splitview, and the window has changed its state. Otherwise,
  // restore its bounds immediately.
EnterAnimationType animation_type =
      window_state->IsSnapped() || IsTopWindow(window_state->window())
? DEFAULT
: IMMEDIATE;
if (old_state_->GetType() == window_state->GetStateType() &&
!window_state->IsNormalStateType()) {
animation_type = IMMEDIATE;
}
old_state_->set_enter_animation_type(animation_type);
// Note: When we return we will destroy ourselves with the |our_reference|.
std::unique_ptr<wm::WindowState::State> our_reference =
window_state->SetStateObject(std::move(old_state_));
}

bool ParseVp9Eotf(const int value, gfx::ColorSpace::TransferID* eotf) {
  switch (value) {
    case 1:
      *eotf = gfx::ColorSpace::TransferID::BT709;
      break;
    case 2:
      // "2" is interpreted as "Unspecified"
      *eotf = gfx::ColorSpace::TransferID::INVALID;
      break;
    case 4:
      *eotf = gfx::ColorSpace::TransferID::GAMMA22;
      break;
    case 5:
      *eotf = gfx::ColorSpace::TransferID::GAMMA28;
      break;
    case 6:
      *eotf = gfx::ColorSpace::TransferID::SMPTE170M;
      break;
    case 7:
      *eotf = gfx::ColorSpace::TransferID::SMPTE240M;
      break;
    case 8:
      *eotf = gfx::ColorSpace::TransferID::LINEAR;
      break;
    case 9:
      *eotf = gfx::ColorSpace::TransferID::LOG;
      break;
    case 10:
      *eotf = gfx::ColorSpace::TransferID::LOG_SQRT;
      break;
    case 11:
      *eotf = gfx::ColorSpace::TransferID::IEC61966_2_4;
      break;
    case 12:
      *eotf = gfx::ColorSpace::TransferID::BT1361_ECG;
      break;
    case 13:
      *eotf = gfx::ColorSpace::TransferID::IEC61966_2_1;
      break;
    case 14:
      *eotf = gfx::ColorSpace::TransferID::BT2020_10;
      break;
    case 15:
      *eotf = gfx::ColorSpace::TransferID::BT2020_12;
      break;
    case 16:
      *eotf = gfx::ColorSpace::TransferID::SMPTEST2084;
      break;
    case 17:
      *eotf = gfx::ColorSpace::TransferID::SMPTEST428_1;
      break;
    default:
      // Includes reserved values of 0, 3, 18 - 255.
      *eotf = gfx::ColorSpace::TransferID::INVALID;
      return false;
  }
  return true;
}

static void ip_cmsg_recv_checksum(struct msghdr *msg, struct sk_buff *skb,
int tlen, int offset)
{
__wsum csum = skb->csum;

if (skb->ip_summed != CHECKSUM_COMPLETE)
return;

	if (offset != 0)
		csum = csum_sub(csum,
				csum_partial(skb_transport_header(skb) + tlen,
					     offset, 0));

put_cmsg(msg, SOL_IP, IP_CHECKSUM, sizeof(__wsum), &csum);
}

