LPSTR tr_esc_str(LPCSTR arg, bool format)
{
LPSTR tmp = NULL;
size_t cs = 0, x, ds, len;
size_t s;

if (NULL == arg)
return NULL;

s = strlen(arg);

/* Find trailing whitespaces */
while ((s > 0) && isspace(arg[s - 1]))
s--;

/* Prepare a initial buffer with the size of the result string. */
ds = s + 1;

if (s)
		tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not allocate string buffer.\n");
exit(-2);
}

/* Copy character for character and check, if it is necessary to escape. */
memset(tmp, 0, ds * sizeof(CHAR));

for (x = 0; x < s; x++)
{
switch (arg[x])
{
case '<':
len = format ? 13 : 4;
ds += len - 1;
				tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not reallocate string buffer.\n");
exit(-3);
}

if (format)
/* coverity[buffer_size] */
strncpy(&tmp[cs], "<replaceable>", len);
else
/* coverity[buffer_size] */
strncpy(&tmp[cs], "&lt;", len);

cs += len;
break;

case '>':
len = format ? 14 : 4;
ds += len - 1;
				tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not reallocate string buffer.\n");
exit(-4);
}

if (format)
/* coverity[buffer_size] */
strncpy(&tmp[cs], "</replaceable>", len);
else
/* coverity[buffer_size] */
strncpy(&tmp[cs], "&lt;", len);

cs += len;
break;

case '\'':
ds += 5;
				tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not reallocate string buffer.\n");
exit(-5);
}

tmp[cs++] = '&';
tmp[cs++] = 'a';
tmp[cs++] = 'p';
tmp[cs++] = 'o';
tmp[cs++] = 's';
tmp[cs++] = ';';
break;

case '"':
ds += 5;
				tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not reallocate string buffer.\n");
exit(-6);
}

tmp[cs++] = '&';
tmp[cs++] = 'q';
tmp[cs++] = 'u';
tmp[cs++] = 'o';
tmp[cs++] = 't';
tmp[cs++] = ';';
break;

case '&':
ds += 4;
				tmp = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

if (NULL == tmp)
{
fprintf(stderr,  "Could not reallocate string buffer.\n");
exit(-7);
}

tmp[cs++] = '&';
tmp[cs++] = 'a';
tmp[cs++] = 'm';
tmp[cs++] = 'p';
tmp[cs++] = ';';
break;

default:
tmp[cs++] = arg[x];
break;
}

/* Assure, the string is '\0' terminated. */
tmp[ds - 1] = '\0';
}

return tmp;
}

int kvm_arch_vcpu_ioctl_run(struct kvm_vcpu *vcpu, struct kvm_run *run)
{
int ret;
sigset_t sigsaved;

	/* Make sure they initialize the vcpu with KVM_ARM_VCPU_INIT *
	if (unlikely(vcpu->arch.target < 0))
return -ENOEXEC;

ret = kvm_vcpu_first_run_init(vcpu);
if (ret)
return ret;

if (run->exit_reason == KVM_EXIT_MMIO) {
ret = kvm_handle_mmio_return(vcpu, vcpu->run);
if (ret)
return ret;
}

if (vcpu->sigset_active)
sigprocmask(SIG_SETMASK, &vcpu->sigset, &sigsaved);

ret = 1;
run->exit_reason = KVM_EXIT_UNKNOWN;
while (ret > 0) {
/*
* Check conditions before entering the guest
*/
cond_resched();

update_vttbr(vcpu->kvm);

if (vcpu->arch.pause)
vcpu_pause(vcpu);

kvm_vgic_flush_hwstate(vcpu);
kvm_timer_flush_hwstate(vcpu);

local_irq_disable();

/*
* Re-check atomic conditions
*/
if (signal_pending(current)) {
ret = -EINTR;
run->exit_reason = KVM_EXIT_INTR;
}

if (ret <= 0 || need_new_vmid_gen(vcpu->kvm)) {
local_irq_enable();
kvm_timer_sync_hwstate(vcpu);
kvm_vgic_sync_hwstate(vcpu);
continue;
}

/**************************************************************
* Enter the guest
*/
trace_kvm_entry(*vcpu_pc(vcpu));
kvm_guest_enter();
vcpu->mode = IN_GUEST_MODE;

ret = kvm_call_hyp(__kvm_vcpu_run, vcpu);

vcpu->mode = OUTSIDE_GUEST_MODE;
vcpu->arch.last_pcpu = smp_processor_id();
kvm_guest_exit();
trace_kvm_exit(*vcpu_pc(vcpu));
/*
* We may have taken a host interrupt in HYP mode (ie
* while executing the guest). This interrupt is still
* pending, as we haven't serviced it yet!
*
* We're now back in SVC mode, with interrupts
* disabled.  Enabling the interrupts now will have
* the effect of taking the interrupt again, in SVC
* mode this time.
*/
local_irq_enable();

/*
* Back from guest
*************************************************************/

kvm_timer_sync_hwstate(vcpu);
kvm_vgic_sync_hwstate(vcpu);

ret = handle_exit(vcpu, run, ret);
}

if (vcpu->sigset_active)
sigprocmask(SIG_SETMASK, &sigsaved, NULL);
return ret;
}

