}
bp += 2;
ND_PRINT((ndo, " RST"));
opts_len -= PGM_OPT_RST_LEN;
break;

case PGM_OPT_CR:
ND_PRINT((ndo, " CR"));
bp += opt_len;
opts_len -= opt_len;
break;

case PGM_OPT_CRQST:
#define PGM_OPT_CRQST_LEN	(2+2)
if (opt_len != PGM_OPT_CRQST_LEN) {
