void CuePoint::Load(IMkvReader* pReader) {
// odbgstream os;
// os << "CuePoint::Load(begin): timecode=" << m_timecode << endl;

if (m_timecode >= 0)  // already loaded
    return;

assert(m_track_positions == NULL);
assert(m_track_positions_count == 0);

long long pos_ = -m_timecode;
const long long element_start = pos_;

long long stop;


{
long len;

    const long long id = ReadUInt(pReader, pos_, len);
    assert(id == 0x3B);  // CuePoint ID
if (id != 0x3B)
      return;

pos_ += len;  // consume ID

const long long size = ReadUInt(pReader, pos_, len);
assert(size >= 0);

pos_ += len; // consume Size field
// pos_ now points to start of payload

stop = pos_ + size;
}

const long long element_size = stop - element_start;

long long pos = pos_;

// First count number of track positions


while (pos < stop) {
long len;

    const long long id = ReadUInt(pReader, pos, len);
    assert(id >= 0);  // TODO
    assert((pos + len) <= stop);

pos += len;  // consume ID

const long long size = ReadUInt(pReader, pos, len);
    assert(size >= 0);
    assert((pos + len) <= stop);

pos += len;  // consume Size field
    assert((pos + size) <= stop);

if (id == 0x33)  // CueTime ID
m_timecode = UnserializeUInt(pReader, pos, size);

else if (id == 0x37) // CueTrackPosition(s) ID

++m_track_positions_count;

pos += size;  // consume payload
    assert(pos <= stop);
}

  assert(m_timecode >= 0);
  assert(m_track_positions_count > 0);

// os << "CuePoint::Load(cont'd): idpos=" << idpos
//   << " timecode=" << m_timecode
//   << endl;

  m_track_positions = new TrackPosition[m_track_positions_count];

// Now parse track positions

TrackPosition* p = m_track_positions;
pos = pos_;


while (pos < stop) {
long len;

    const long long id = ReadUInt(pReader, pos, len);
    assert(id >= 0);  // TODO
    assert((pos + len) <= stop);

pos += len;  // consume ID

const long long size = ReadUInt(pReader, pos, len);
assert(size >= 0);
assert((pos + len) <= stop);

pos += len; // consume Size field
assert((pos + size) <= stop);


if (id == 0x37) {  // CueTrackPosition(s) ID
TrackPosition& tp = *p++;
      tp.Parse(pReader, pos, size);
}

pos += size;  // consume payload
    assert(pos <= stop);
}

assert(size_t(p - m_track_positions) == m_track_positions_count);

m_element_start = element_start;
m_element_size = element_size;
}

void RenderBlock::styleDidChange(StyleDifference diff, const RenderStyle* oldStyle)
{
RenderBox::styleDidChange(diff, oldStyle);

RenderStyle* newStyle = style();

if (!isAnonymousBlock()) {
// Ensure that all of our continuation blocks pick up the new style.
for (RenderBlock* currCont = blockElementContinuation(); currCont; currCont = currCont->blockElementContinuation()) {
RenderBoxModelObject* nextCont = currCont->continuation();
currCont->setContinuation(0);
currCont->setStyle(newStyle);
currCont->setContinuation(nextCont);
}
}

if (FastTextAutosizer* textAutosizer = document().fastTextAutosizer())
textAutosizer->record(this);

propagateStyleToAnonymousChildren(true);
invalidateLineHeight();

// It's possible for our border/padding to change, but for the overall logical width of the block to
// end up being the same. We keep track of this change so in layoutBlock, we can know to set relayoutChildren=true.
    m_hasBorderOrPaddingLogicalWidthChanged = oldStyle && diff == StyleDifferenceLayout && needsLayout() && borderOrPaddingLogicalWidthChanged(oldStyle, newStyle);

// If the style has unloaded images, want to notify the ResourceLoadPriorityOptimizer so that
// network priorities can be set.
Vector<ImageResource*> images;
appendImagesFromStyle(images, *newStyle);
if (images.isEmpty())
ResourceLoadPriorityOptimizer::resourceLoadPriorityOptimizer()->removeRenderObject(this);
else
ResourceLoadPriorityOptimizer::resourceLoadPriorityOptimizer()->addRenderObject(this);
}

