tt_face_load_kern( TT_Face    face,
FT_Stream  stream )
{
FT_Error   error;
FT_ULong   table_size;
FT_Byte*   p;
FT_Byte*   p_limit;
FT_UInt    nn, num_tables;
FT_UInt32  avail = 0, ordered = 0;


/* the kern table is optional; exit silently if it is missing */
error = face->goto_table( face, TTAG_kern, stream, &table_size );
if ( error )
goto Exit;

if ( table_size < 4 )  /* the case of a malformed table */
{
FT_ERROR(( "tt_face_load_kern:"
" kerning table is too small - ignored\n" ));
error = FT_THROW( Table_Missing );
goto Exit;
}

if ( FT_FRAME_EXTRACT( table_size, face->kern_table ) )
{
FT_ERROR(( "tt_face_load_kern:"
" could not extract kerning table\n" ));
goto Exit;
}

face->kern_table_size = table_size;

p       = face->kern_table;
p_limit = p + table_size;

p         += 2; /* skip version */
num_tables = FT_NEXT_USHORT( p );

if ( num_tables > 32 ) /* we only support up to 32 sub-tables */
num_tables = 32;

for ( nn = 0; nn < num_tables; nn++ )
{
FT_UInt    num_pairs, length, coverage;
FT_Byte*   p_next;
FT_UInt32  mask = (FT_UInt32)1UL << nn;


if ( p + 6 > p_limit )
break;

p_next = p;

p += 2; /* skip version */
length   = FT_NEXT_USHORT( p );
coverage = FT_NEXT_USHORT( p );

      if ( length <= 6 )
break;

p_next += length;

if ( p_next > p_limit )  /* handle broken table */
p_next = p_limit;

/* only use horizontal kerning tables */
if ( ( coverage & ~8 ) != 0x0001 ||
p + 8 > p_limit             )
goto NextTable;

num_pairs = FT_NEXT_USHORT( p );
p        += 6;

if ( ( p_next - p ) < 6 * (int)num_pairs ) /* handle broken count */
num_pairs = (FT_UInt)( ( p_next - p ) / 6 );

avail |= mask;

/*
*  Now check whether the pairs in this table are ordered.
*  We then can use binary search.
*/
if ( num_pairs > 0 )
{
FT_ULong  count;
FT_ULong  old_pair;


old_pair = FT_NEXT_ULONG( p );
p       += 2;

for ( count = num_pairs - 1; count > 0; count-- )
{
FT_UInt32  cur_pair;


cur_pair = FT_NEXT_ULONG( p );
if ( cur_pair <= old_pair )
break;

p += 2;
old_pair = cur_pair;
}

if ( count == 0 )
ordered |= mask;
}

NextTable:
p = p_next;
}

face->num_kern_tables = nn;
face->kern_avail_bits = avail;
face->kern_order_bits = ordered;

Exit:
return error;
}

BGD_DECLARE(gdImagePtr) gdImageCreateFromTgaCtx(gdIOCtx* ctx)
{
int bitmap_caret = 0;
oTga *tga = NULL;
/*	int pixel_block_size = 0;
int image_block_size = 0; */
volatile gdImagePtr image = NULL;
int x = 0;
int y = 0;

tga = (oTga *) gdMalloc(sizeof(oTga));
if (!tga) {
return NULL;
}

tga->bitmap = NULL;
tga->ident = NULL;

if (read_header_tga(ctx, tga) < 0) {
free_tga(tga);
return NULL;
}

/*TODO: Will this be used?
pixel_block_size = tga->bits / 8;
image_block_size = (tga->width * tga->height) * pixel_block_size;
*/

if (read_image_tga(ctx, tga) < 0) {
free_tga(tga);
return NULL;
}

image = gdImageCreateTrueColor((int)tga->width, (int)tga->height );

if (image == 0) {
free_tga( tga );
return NULL;
}

/*!	\brief Populate GD image object
*  Copy the pixel data from our tga bitmap buffer into the GD image
*  Disable blending and save the alpha channel per default
*/
if (tga->alphabits) {
gdImageAlphaBlending(image, 0);
gdImageSaveAlpha(image, 1);
}

/* TODO: use alphabits as soon as we support 24bit and other alpha bps (ie != 8bits) */
for (y = 0; y < tga->height; y++) {
register int *tpix = image->tpixels[y];
for ( x = 0; x < tga->width; x++, tpix++) {
if (tga->bits == TGA_BPP_24) {
*tpix = gdTrueColor(tga->bitmap[bitmap_caret + 2], tga->bitmap[bitmap_caret + 1], tga->bitmap[bitmap_caret]);
bitmap_caret += 3;
			} else if (tga->bits == TGA_BPP_32 || tga->alphabits) {
register int a = tga->bitmap[bitmap_caret + 3];

*tpix = gdTrueColorAlpha(tga->bitmap[bitmap_caret + 2], tga->bitmap[bitmap_caret + 1], tga->bitmap[bitmap_caret], gdAlphaMax - (a >> 1));
bitmap_caret += 4;
}
}
}

if (tga->flipv && tga->fliph) {
gdImageFlipBoth(image);
} else if (tga->flipv) {
gdImageFlipVertical(image);
} else if (tga->fliph) {
gdImageFlipHorizontal(image);
}

free_tga(tga);

return image;
}

void set_cfg_option(char *opt_string)
{
	char *sep, *sep2, szSec[1024], szKey[1024], szVal[1024];
	sep = strchr(opt_string, ':');
	if (!sep) {
		fprintf(stderr, "Badly formatted option %s - expected Section:Name=Value\n", opt_string);
		return;
 	}
 	{
 		const size_t sepIdx = sep - opt_string;
 		strncpy(szSec, opt_string, sepIdx);
 		szSec[sepIdx] = 0;
 	}
	sep ++;
	sep2 = strchr(sep, '=');
	if (!sep2) {
		fprintf(stderr, "Badly formatted option %s - expected Section:Name=Value\n", opt_string);
		return;
 	}
 	{
 		const size_t sepIdx = sep2 - sep;
 		strncpy(szKey, sep, sepIdx);
 		szKey[sepIdx] = 0;
 		strcpy(szVal, sep2+1);
 	}

	if (!stricmp(szKey, "*")) {
		if (stricmp(szVal, "null")) {
			fprintf(stderr, "Badly formatted option %s - expected Section:*=null\n", opt_string);
			return;
		}
		gf_cfg_del_section(cfg_file, szSec);
		return;
	}

	if (!stricmp(szVal, "null")) {
		szVal[0]=0;
	}
	gf_cfg_set_key(cfg_file, szSec, szKey, szVal[0] ? szVal : NULL);
}

