int bpf_check(struct bpf_prog **prog, union bpf_attr *attr)
{
	struct bpf_verifier_env *env;
	struct bpf_verifer_log *log;
	int ret = -EINVAL;

	/* no program is valid */
	if (ARRAY_SIZE(bpf_verifier_ops) == 0)
		return -EINVAL;

	/* 'struct bpf_verifier_env' can be global, but since it's not small,
	 * allocate/free it every time bpf_check() is called
	 */
	env = kzalloc(sizeof(struct bpf_verifier_env), GFP_KERNEL);
	if (!env)
		return -ENOMEM;
	log = &env->log;

	env->insn_aux_data = vzalloc(sizeof(struct bpf_insn_aux_data) *
				     (*prog)->len);
	ret = -ENOMEM;
	if (!env->insn_aux_data)
		goto err_free_env;
	env->prog = *prog;
	env->ops = bpf_verifier_ops[env->prog->type];

	/* grab the mutex to protect few globals used by verifier */
	mutex_lock(&bpf_verifier_lock);

	if (attr->log_level || attr->log_buf || attr->log_size) {
		/* user requested verbose verifier output
		 * and supplied buffer to store the verification trace
		 */
		log->level = attr->log_level;
		log->ubuf = (char __user *) (unsigned long) attr->log_buf;
		log->len_total = attr->log_size;

		ret = -EINVAL;
		/* log attributes have to be sane */
		if (log->len_total < 128 || log->len_total > UINT_MAX >> 8 ||
		    !log->level || !log->ubuf)
			goto err_unlock;
	}

	env->strict_alignment = !!(attr->prog_flags & BPF_F_STRICT_ALIGNMENT);
	if (!IS_ENABLED(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS))
		env->strict_alignment = true;

	if (env->prog->aux->offload) {
		ret = bpf_prog_offload_verifier_prep(env);
		if (ret)
			goto err_unlock;
	}

	ret = replace_map_fd_with_map_ptr(env);
	if (ret < 0)
		goto skip_full_check;

	env->explored_states = kcalloc(env->prog->len,
				       sizeof(struct bpf_verifier_state_list *),
				       GFP_USER);
	ret = -ENOMEM;
	if (!env->explored_states)
		goto skip_full_check;

	ret = check_cfg(env);
	if (ret < 0)
		goto skip_full_check;

	env->allow_ptr_leaks = capable(CAP_SYS_ADMIN);

	ret = do_check(env);
	if (env->cur_state) {
		free_verifier_state(env->cur_state, true);
		env->cur_state = NULL;
	}

skip_full_check:
 	while (!pop_stack(env, NULL, NULL));
 	free_states(env);

 	if (ret == 0)
 		/* program is valid, convert *(u32*)(ctx + off) accesses */
 		ret = convert_ctx_accesses(env);

	if (ret == 0)
		ret = fixup_bpf_calls(env);

	if (log->level && bpf_verifier_log_full(log))
		ret = -ENOSPC;
	if (log->level && !log->ubuf) {
		ret = -EFAULT;
		goto err_release_maps;
	}

	if (ret == 0 && env->used_map_cnt) {
		/* if program passed verifier, update used_maps in bpf_prog_info */
		env->prog->aux->used_maps = kmalloc_array(env->used_map_cnt,
							  sizeof(env->used_maps[0]),
							  GFP_KERNEL);

		if (!env->prog->aux->used_maps) {
			ret = -ENOMEM;
			goto err_release_maps;
		}

		memcpy(env->prog->aux->used_maps, env->used_maps,
		       sizeof(env->used_maps[0]) * env->used_map_cnt);
		env->prog->aux->used_map_cnt = env->used_map_cnt;

		/* program is valid. Convert pseudo bpf_ld_imm64 into generic
		 * bpf_ld_imm64 instructions
		 */
		convert_pseudo_ld_imm64(env);
	}

err_release_maps:
	if (!env->prog->aux->used_maps)
		/* if we didn't copy map pointers into bpf_prog_info, release
		 * them now. Otherwise free_bpf_prog_info() will release them.
		 */
		release_maps(env);
	*prog = env->prog;
err_unlock:
	mutex_unlock(&bpf_verifier_lock);
	vfree(env->insn_aux_data);
err_free_env:
	kfree(env);
	return ret;
}

_WM_ParseNewMidi(uint8_t *midi_data, uint32_t midi_size) {
struct _mdi *mdi;

uint32_t tmp_val;
uint32_t midi_type;
    uint32_t track_size;
uint8_t **tracks;
uint32_t end_of_tracks = 0;
uint32_t no_tracks;
uint32_t i;
uint32_t divisions = 96;
uint32_t tempo = 500000;
float samples_per_delta_f = 0.0;

uint32_t sample_count = 0;
float sample_count_f = 0.0;
float sample_remainder = 0.0;
uint8_t *sysex_store = NULL;
  uint32_t sysex_store_len = 0;

uint32_t *track_delta;
uint8_t *track_end;
uint32_t smallest_delta = 0;
uint32_t subtract_delta = 0;
  uint32_t tmp_length = 0;
  uint8_t current_event = 0;
  uint8_t current_event_ch = 0;
uint8_t *running_event;
uint32_t setup_ret = 0;

if (midi_size < 14) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(too short)", 0);
return (NULL);
}

if (!memcmp(midi_data, "RIFF", 4)) {
if (midi_size < 34) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(too short)", 0);
return (NULL);
}
midi_data += 20;
midi_size -= 20;
}

if (memcmp(midi_data, "MThd", 4)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_MIDI, NULL, 0);
return (NULL);
}
midi_data += 4;
midi_size -= 4;

/*
* Get Midi Header Size - must always be 6
*/
tmp_val = *midi_data++ << 24;
tmp_val |= *midi_data++ << 16;
tmp_val |= *midi_data++ << 8;
tmp_val |= *midi_data++;
midi_size -= 4;
if (tmp_val != 6) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, NULL, 0);
return (NULL);
}

/*
* Get Midi Format - we only support 0, 1 & 2
*/
tmp_val = *midi_data++ << 8;
tmp_val |= *midi_data++;
midi_size -= 2;
if (tmp_val > 2) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_INVALID, NULL, 0);
return (NULL);
}
midi_type = tmp_val;

/*
* Get No. of Tracks
*/
tmp_val = *midi_data++ << 8;
tmp_val |= *midi_data++;
midi_size -= 2;
if (tmp_val < 1) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(no tracks)", 0);
return (NULL);
}
no_tracks = tmp_val;

/*
* Check that type 0 midi file has only 1 track
*/
if ((midi_type == 0) && (no_tracks > 1)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_INVALID, "(expected 1 track for type 0 midi file, found more)", 0);
return (NULL);
}

/*
* Get Divisions
*/
divisions = *midi_data++ << 8;
divisions |= *midi_data++;
midi_size -= 2;
if (divisions & 0x00008000) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_INVALID, NULL, 0);
return (NULL);
}

samples_per_delta_f = _WM_GetSamplesPerTick(divisions, tempo);

mdi = _WM_initMDI();
_WM_midi_setup_divisions(mdi,divisions);

tracks = malloc(sizeof(uint8_t *) * no_tracks);
track_delta = malloc(sizeof(uint32_t) * no_tracks);
track_end = malloc(sizeof(uint8_t) * no_tracks);
running_event = malloc(sizeof(uint8_t) * no_tracks);

smallest_delta = 0xffffffff;
for (i = 0; i < no_tracks; i++) {
if (midi_size < 8) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(too short)", 0);
goto _end;
}
if (memcmp(midi_data, "MTrk", 4) != 0) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(missing track header)", 0);
goto _end;
}
midi_data += 4;
midi_size -= 4;

        track_size = *midi_data++ << 24;
        track_size |= *midi_data++ << 16;
        track_size |= *midi_data++ << 8;
        track_size |= *midi_data++;
midi_size -= 4;
        if (midi_size < track_size) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(too short)", 0);
goto _end;
}
        if (track_size < 3) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(bad track size)", 0);
goto _end;
}
        if ((midi_data[track_size - 3] != 0xFF)
                || (midi_data[track_size - 2] != 0x2F)
                || (midi_data[track_size - 1] != 0x00)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(missing EOT)", 0);
goto _end;
}
tracks[i] = midi_data;
        midi_data += track_size;
        midi_size -= track_size;
track_end[i] = 0;
running_event[i] = 0;
track_delta[i] = 0;

while (*tracks[i] > 0x7F) {
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;
}
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;

if (midi_type == 1 ) {
if (track_delta[i] < smallest_delta) {
smallest_delta = track_delta[i];
}
} else {
/*
* Type 0 & 2 midi only needs delta from 1st track
* for initial sample calculations.
*/
if (i == 0) smallest_delta = track_delta[i];
}
}

subtract_delta = smallest_delta;
sample_count_f = (((float) smallest_delta * samples_per_delta_f) + sample_remainder);
sample_count = (uint32_t) sample_count_f;
sample_remainder = sample_count_f - (float) sample_count;

mdi->events[mdi->event_count - 1].samples_to_next += sample_count;
mdi->extra_info.approx_total_samples += sample_count;

/*
* Handle type 0 & 2 the same, but type 1 differently
*/
if (midi_type == 1) {
/* Type 1 */
while (end_of_tracks != no_tracks) {
smallest_delta = 0;
for (i = 0; i < no_tracks; i++) {
if (track_end[i])
continue;
if (track_delta[i]) {
track_delta[i] -= subtract_delta;
if (track_delta[i]) {
if ((!smallest_delta)
|| (smallest_delta > track_delta[i])) {
smallest_delta = track_delta[i];
}
continue;
}
}
do {
                    setup_ret = _WM_SetupMidiEvent(mdi, tracks[i], running_event[i]);
if (setup_ret == 0) {
goto _end;
}
if (tracks[i][0] > 0x7f) {
if (tracks[i][0] < 0xf0) {
/* Events 0x80 - 0xef set running event */
running_event[i] = tracks[i][0];
} else if ((tracks[i][0] == 0xf0) || (tracks[i][0] == 0xf7)) {
/* Sysex resets running event */
running_event[i] = 0;
} else if ((tracks[i][0] == 0xff) && (tracks[i][1] == 0x2f) && (tracks[i][2] == 0x00)) {
/* End of Track */
end_of_tracks++;
track_end[i] = 1;
tracks[i] += 3;
goto NEXT_TRACK;
} else if ((tracks[i][0] == 0xff) && (tracks[i][1] == 0x51) && (tracks[i][2] == 0x03)) {
/* Tempo */
tempo = (tracks[i][3] << 16) + (tracks[i][4] << 8)+ tracks[i][5];
if (!tempo)
tempo = 500000;

samples_per_delta_f = _WM_GetSamplesPerTick(divisions, tempo);
}
}
tracks[i] += setup_ret;

if (*tracks[i] > 0x7f) {
do {
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;
} while (*tracks[i] > 0x7f);
}
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;
} while (!track_delta[i]);
if ((!smallest_delta) || (smallest_delta > track_delta[i])) {
smallest_delta = track_delta[i];
}
NEXT_TRACK: continue;
}

subtract_delta = smallest_delta;
sample_count_f = (((float) smallest_delta * samples_per_delta_f)
+ sample_remainder);
sample_count = (uint32_t) sample_count_f;
sample_remainder = sample_count_f - (float) sample_count;

mdi->events[mdi->event_count - 1].samples_to_next += sample_count;
mdi->extra_info.approx_total_samples += sample_count;
}
} else {
/* Type 0 & 2 */
if (midi_type == 2) {
mdi->is_type2 = 1;
}
sample_remainder = 0.0;
for (i = 0; i < no_tracks; i++) {
running_event[i] = 0;
do {
                setup_ret = _WM_SetupMidiEvent(mdi, tracks[i], running_event[i]);
if (setup_ret == 0) {
goto _end;
}
if (tracks[i][0] > 0x7f) {
if (tracks[i][0] < 0xf0) {
/* Events 0x80 - 0xef set running event */
running_event[i] = tracks[i][0];
} else if ((tracks[i][0] == 0xf0) || (tracks[i][0] == 0xf7)) {
/* Sysex resets running event */
running_event[i] = 0;
} else if ((tracks[i][0] == 0xff) && (tracks[i][1] == 0x2f) && (tracks[i][2] == 0x00)) {
/* End of Track */
track_end[i] = 1;
goto NEXT_TRACK2;
} else if ((tracks[i][0] == 0xff) && (tracks[i][1] == 0x51) && (tracks[i][2] == 0x03)) {
/* Tempo */
tempo = (tracks[i][3] << 16) + (tracks[i][4] << 8)+ tracks[i][5];
if (!tempo)
tempo = 500000;

samples_per_delta_f = _WM_GetSamplesPerTick(divisions, tempo);
}
}
tracks[i] += setup_ret;

track_delta[i] = 0;
if (*tracks[i] > 0x7f) {
do {
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;
} while (*tracks[i] > 0x7f);
}
track_delta[i] = (track_delta[i] << 7) + (*tracks[i] & 0x7F);
tracks[i]++;

sample_count_f = (((float) track_delta[i] * samples_per_delta_f)
+ sample_remainder);
sample_count = (uint32_t) sample_count_f;
sample_remainder = sample_count_f - (float) sample_count;
mdi->events[mdi->event_count - 1].samples_to_next += sample_count;
mdi->extra_info.approx_total_samples += sample_count;
NEXT_TRACK2:
smallest_delta = track_delta[i]; /* Added just to keep Xcode happy */
UNUSED(smallest_delta); /* Added to just keep clang happy */
} while (track_end[i] == 0);
}
}

if ((mdi->reverb = _WM_init_reverb(_WM_SampleRate, _WM_reverb_room_width,
_WM_reverb_room_length, _WM_reverb_listen_posx, _WM_reverb_listen_posy))
== NULL) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_MEM, "to init reverb", 0);
goto _end;
}

mdi->extra_info.current_sample = 0;
mdi->current_event = &mdi->events[0];
mdi->samples_to_mix = 0;
mdi->note = NULL;

_WM_ResetToStart(mdi);

_end:   free(sysex_store);
free(track_end);
free(track_delta);
free(running_event);
free(tracks);
if (mdi->reverb) return (mdi);
_WM_freeMDI(mdi);
return (NULL);
}

void OneClickSigninHelper::ShowInfoBarIfPossible(net::URLRequest* request,
ProfileIOData* io_data,
int child_id,
int route_id) {
std::string google_chrome_signin_value;
std::string google_accounts_signin_value;
request->GetResponseHeaderByName("Google-Chrome-SignIn",
&google_chrome_signin_value);
request->GetResponseHeaderByName("Google-Accounts-SignIn",
&google_accounts_signin_value);

if (!google_accounts_signin_value.empty() ||
!google_chrome_signin_value.empty()) {
VLOG(1) << "OneClickSigninHelper::ShowInfoBarIfPossible:"
<< " g-a-s='" << google_accounts_signin_value << "'"
<< " g-c-s='" << google_chrome_signin_value << "'";
}

  if (!gaia::IsGaiaSignonRealm(request->original_url().GetOrigin()))
return;

// Parse Google-Accounts-SignIn.
std::vector<std::pair<std::string, std::string> > pairs;
base::SplitStringIntoKeyValuePairs(google_accounts_signin_value, '=', ',',
&pairs);
std::string session_index;
std::string email;
for (size_t i = 0; i < pairs.size(); ++i) {
const std::pair<std::string, std::string>& pair = pairs[i];
const std::string& key = pair.first;
const std::string& value = pair.second;
if (key == "email") {
TrimString(value, "\"", &email);
} else if (key == "sessionindex") {
session_index = value;
}
}

// Later in the chain of this request, we'll need to check the email address
// in the IO thread (see CanOfferOnIOThread).  So save the email address as
// user data on the request (only for web-based flow).
if (!email.empty())
io_data->set_reverse_autologin_pending_email(email);

if (!email.empty() || !session_index.empty()) {
VLOG(1) << "OneClickSigninHelper::ShowInfoBarIfPossible:"
<< " email=" << email
<< " sessionindex=" << session_index;
}

// Parse Google-Chrome-SignIn.
AutoAccept auto_accept = AUTO_ACCEPT_NONE;
signin::Source source = signin::SOURCE_UNKNOWN;
GURL continue_url;
std::vector<std::string> tokens;
base::SplitString(google_chrome_signin_value, ',', &tokens);
for (size_t i = 0; i < tokens.size(); ++i) {
const std::string& token = tokens[i];
if (token == "accepted") {
auto_accept = AUTO_ACCEPT_ACCEPTED;
} else if (token == "configure") {
auto_accept = AUTO_ACCEPT_CONFIGURE;
} else if (token == "rejected-for-profile") {
auto_accept = AUTO_ACCEPT_REJECTED_FOR_PROFILE;
}
}

// If this is an explicit sign in (i.e., first run, NTP, Apps page, menu,
// settings) then force the auto accept type to explicit.
source = GetSigninSource(request->url(), &continue_url);
if (source != signin::SOURCE_UNKNOWN)
auto_accept = AUTO_ACCEPT_EXPLICIT;

if (auto_accept != AUTO_ACCEPT_NONE) {
VLOG(1) << "OneClickSigninHelper::ShowInfoBarIfPossible:"
<< " auto_accept=" << auto_accept;
}

// If |session_index|, |email|, |auto_accept|, and |continue_url| all have
// their default value, don't bother posting a task to the UI thread.
// It will be a noop anyway.
//
// The two headers above may (but not always) come in different http requests
// so a post to the UI thread is still needed if |auto_accept| is not its
// default value, but |email| and |session_index| are.
if (session_index.empty() && email.empty() &&
auto_accept == AUTO_ACCEPT_NONE && !continue_url.is_valid()) {
return;
}

content::BrowserThread::PostTask(
content::BrowserThread::UI, FROM_HERE,
base::Bind(&OneClickSigninHelper::ShowInfoBarUIThread, session_index,
email, auto_accept, source, continue_url, child_id, route_id));
}

lmp_print_data_link_subobjs(netdissect_options *ndo, const u_char *obj_tptr,
                            int total_subobj_len, int offset)
{
    int hexdump = FALSE;
    int subobj_type, subobj_len;

    union { /* int to float conversion buffer */
        float f;
        uint32_t i;
    } bw;

    while (total_subobj_len > 0 && hexdump == FALSE ) {
	subobj_type = EXTRACT_8BITS(obj_tptr + offset);
	subobj_len  = EXTRACT_8BITS(obj_tptr + offset + 1);
	ND_PRINT((ndo, "\n\t    Subobject, Type: %s (%u), Length: %u",
		tok2str(lmp_data_link_subobj,
			"Unknown",
			subobj_type),
			subobj_type,
			subobj_len));
	if (subobj_len < 4) {
	    ND_PRINT((ndo, " (too short)"));
	    break;
	}
	if ((subobj_len % 4) != 0) {
	    ND_PRINT((ndo, " (not a multiple of 4)"));
	    break;
	}
	if (total_subobj_len < subobj_len) {
	    ND_PRINT((ndo, " (goes past the end of the object)"));
	    break;
	}
	switch(subobj_type) {
	case INT_SWITCHING_TYPE_SUBOBJ:
	    ND_PRINT((ndo, "\n\t      Switching Type: %s (%u)",
		tok2str(gmpls_switch_cap_values,
			"Unknown",
			EXTRACT_8BITS(obj_tptr + offset + 2)),
			EXTRACT_8BITS(obj_tptr + offset + 2)));
	    ND_PRINT((ndo, "\n\t      Encoding Type: %s (%u)",
		tok2str(gmpls_encoding_values,
 			"Unknown",
 			EXTRACT_8BITS(obj_tptr + offset + 3)),
 			EXTRACT_8BITS(obj_tptr + offset + 3)));
 	    bw.i = EXTRACT_32BITS(obj_tptr+offset+4);
 	    ND_PRINT((ndo, "\n\t      Min Reservable Bandwidth: %.3f Mbps",
                 bw.f*8/1000000));
	    bw.i = EXTRACT_32BITS(obj_tptr+offset+8);
	    ND_PRINT((ndo, "\n\t      Max Reservable Bandwidth: %.3f Mbps",
                bw.f*8/1000000));
	    break;
	case WAVELENGTH_SUBOBJ:
	    ND_PRINT((ndo, "\n\t      Wavelength: %u",
		EXTRACT_32BITS(obj_tptr+offset+4)));
	    break;
	default:
	    /* Any Unknown Subobject ==> Exit loop */
	    hexdump=TRUE;
	    break;
	}
	total_subobj_len-=subobj_len;
 	offset+=subobj_len;
     }
     return (hexdump);
 }

 static int smacker_decode_tree(BitstreamContext *bc, HuffContext *hc,
                                uint32_t prefix, int length)
 {
     if (!bitstream_read_bit(bc)) { // Leaf
         if(hc->current >= 256){
             av_log(NULL, AV_LOG_ERROR, "Tree size exceeded!\n");
            return AVERROR_INVALIDDATA;
        }
        if(length){
            hc->bits[hc->current] = prefix;
            hc->lengths[hc->current] = length;
        } else {
            hc->bits[hc->current] = 0;
            hc->lengths[hc->current] = 0;
        }
        hc->values[hc->current] = bitstream_read(bc, 8);
        hc->current++;
        if(hc->maxlength < length)
            hc->maxlength = length;
        return 0;
    } else { //Node
        int r;
        length++;
        r = smacker_decode_tree(bc, hc, prefix, length);
        if(r)
            return r;
        return smacker_decode_tree(bc, hc, prefix | (1 << (length - 1)), length);
    }
}

