HAL_CBACK(bt_hal_cbacks, energy_info_cb, &energy_info);
break;
}
#endif

case BTA_DM_AUTHORIZE_EVT:
case BTA_DM_SIG_STRENGTH_EVT:
case BTA_DM_SP_RMT_OOB_EVT:
case BTA_DM_SP_KEYPRESS_EVT:
