static Image *ReadIPLImage(const ImageInfo *image_info,ExceptionInfo *exception)
{

/*
Declare variables.
*/
Image *image;

MagickBooleanType status;
register PixelPacket *q;
unsigned char magick[12], *pixels;
ssize_t count;
ssize_t y;
size_t t_count=0;
size_t length;
IPLInfo
ipl_info;
QuantumFormatType
quantum_format;
QuantumInfo
*quantum_info;
QuantumType
quantum_type;

/*
Open Image
*/

assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if ( image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent, GetMagickModule(), "%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}

/*
Read IPL image
*/

/*
Determine endianness
If we get back "iiii", we have LSB,"mmmm", MSB
*/
count=ReadBlob(image,4,magick);
(void) count;
if((LocaleNCompare((char *) magick,"iiii",4) == 0))
image->endian=LSBEndian;
else{
if((LocaleNCompare((char *) magick,"mmmm",4) == 0))
image->endian=MSBEndian;
else{
ThrowReaderException(CorruptImageError, "ImproperImageHeader");
}
}
/* Skip o'er the next 8 bytes (garbage) */
count=ReadBlob(image, 8, magick);
/*
Excellent, now we read the header unimpeded.
*/
count=ReadBlob(image,4,magick);
if((LocaleNCompare((char *) magick,"data",4) != 0))
ThrowReaderException(CorruptImageError, "ImproperImageHeader");
ipl_info.size=ReadBlobLong(image);
ipl_info.width=ReadBlobLong(image);
ipl_info.height=ReadBlobLong(image);
if((ipl_info.width == 0UL) || (ipl_info.height == 0UL))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
ipl_info.colors=ReadBlobLong(image);
if(ipl_info.colors == 3){ SetImageColorspace(image,sRGBColorspace);}
else { image->colorspace = GRAYColorspace; }
ipl_info.z=ReadBlobLong(image);
ipl_info.time=ReadBlobLong(image);

ipl_info.byteType=ReadBlobLong(image);


/* Initialize Quantum Info */

switch (ipl_info.byteType) {
case 0:
ipl_info.depth=8;
quantum_format = UnsignedQuantumFormat;
break;
case 1:
ipl_info.depth=16;
quantum_format = SignedQuantumFormat;
break;
case 2:
ipl_info.depth=16;
quantum_format = UnsignedQuantumFormat;
break;
case 3:
ipl_info.depth=32;
quantum_format = SignedQuantumFormat;
break;
case 4: ipl_info.depth=32;
quantum_format = FloatingPointQuantumFormat;
break;
case 5:
ipl_info.depth=8;
quantum_format = UnsignedQuantumFormat;
break;
case 6:
ipl_info.depth=16;
quantum_format = UnsignedQuantumFormat;
break;
case 10:
ipl_info.depth=64;
quantum_format = FloatingPointQuantumFormat;
break;
default:
ipl_info.depth=16;
quantum_format = UnsignedQuantumFormat;
break;
}

/*
Set number of scenes of image
*/

SetHeaderFromIPL(image, &ipl_info);

/* Thats all we need if we are pinging. */
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}
length=image->columns;
quantum_type=GetQuantumType(image,exception);
do
{
SetHeaderFromIPL(image, &ipl_info);

  if ((image_info->ping != MagickFalse) && (image_info->number_scenes != 0))
if (image->scene >= (image_info->scene+image_info->number_scenes-1))
break;
/*
printf("Length: %.20g, Memory size: %.20g\n", (double) length,(double)
image->depth);
*/
quantum_info=AcquireQuantumInfo(image_info,image);
if (quantum_info == (QuantumInfo *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
status=SetQuantumFormat(image,quantum_info,quantum_format);
if (status == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
pixels=GetQuantumPixels(quantum_info);
if(image->columns != ipl_info.width){
/*
printf("Columns not set correctly!  Wanted: %.20g, got: %.20g\n",
(double) ipl_info.width, (double) image->columns);
*/
}

/*
Covert IPL binary to pixel packets
*/

if(ipl_info.colors == 1){
for(y = 0; y < (ssize_t) image->rows; y++){
(void) ReadBlob(image, length*image->depth/8, pixels);
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
(void) ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,
GrayQuantum,pixels,exception);
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
}
else{
for(y = 0; y < (ssize_t) image->rows; y++){
(void) ReadBlob(image, length*image->depth/8, pixels);
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
(void) ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,
RedQuantum,pixels,exception);
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
for(y = 0; y < (ssize_t) image->rows; y++){
(void) ReadBlob(image, length*image->depth/8, pixels);
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
(void) ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,
GreenQuantum,pixels,exception);
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
for(y = 0; y < (ssize_t) image->rows; y++){
(void) ReadBlob(image, length*image->depth/8, pixels);
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
(void) ImportQuantumPixels(image,(CacheView *) NULL,quantum_info,
BlueQuantum,pixels,exception);
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
}
}
SetQuantumImageType(image,quantum_type);

t_count++;
quantum_info = DestroyQuantumInfo(quantum_info);

if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
break;
}
if(t_count < ipl_info.z * ipl_info.time){
/*
Proceed to next image.
*/
AcquireNextImage(image_info, image);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
status=SetImageProgress(image,LoadImagesTag,TellBlob(image),
GetBlobSize(image));
if (status == MagickFalse)
break;
}
} while (t_count < ipl_info.z*ipl_info.time);
CloseBlob(image);
return(GetFirstImageInList(image));
}

static int cp2112_probe(struct hid_device *hdev, const struct hid_device_id *id)
{
struct cp2112_device *dev;
u8 buf[3];
struct cp2112_smbus_config_report config;
int ret;

dev = devm_kzalloc(&hdev->dev, sizeof(*dev), GFP_KERNEL);
if (!dev)
return -ENOMEM;

dev->in_out_buffer = devm_kzalloc(&hdev->dev, CP2112_REPORT_MAX_LENGTH,
GFP_KERNEL);
if (!dev->in_out_buffer)
return -ENOMEM;

	spin_lock_init(&dev->lock);

ret = hid_parse(hdev);
if (ret) {
hid_err(hdev, "parse failed\n");
return ret;
}

ret = hid_hw_start(hdev, HID_CONNECT_HIDRAW);
if (ret) {
hid_err(hdev, "hw start failed\n");
return ret;
}

ret = hid_hw_open(hdev);
if (ret) {
hid_err(hdev, "hw open failed\n");
goto err_hid_stop;
}

ret = hid_hw_power(hdev, PM_HINT_FULLON);
if (ret < 0) {
hid_err(hdev, "power management error: %d\n", ret);
goto err_hid_close;
}

ret = cp2112_hid_get(hdev, CP2112_GET_VERSION_INFO, buf, sizeof(buf),
HID_FEATURE_REPORT);
if (ret != sizeof(buf)) {
hid_err(hdev, "error requesting version\n");
if (ret >= 0)
ret = -EIO;
goto err_power_normal;
}

hid_info(hdev, "Part Number: 0x%02X Device Version: 0x%02X\n",
buf[1], buf[2]);

ret = cp2112_hid_get(hdev, CP2112_SMBUS_CONFIG, (u8 *)&config,
sizeof(config), HID_FEATURE_REPORT);
if (ret != sizeof(config)) {
hid_err(hdev, "error requesting SMBus config\n");
if (ret >= 0)
ret = -EIO;
goto err_power_normal;
}

config.retry_time = cpu_to_be16(1);

ret = cp2112_hid_output(hdev, (u8 *)&config, sizeof(config),
HID_FEATURE_REPORT);
if (ret != sizeof(config)) {
hid_err(hdev, "error setting SMBus config\n");
if (ret >= 0)
ret = -EIO;
goto err_power_normal;
}

hid_set_drvdata(hdev, (void *)dev);
dev->hdev		= hdev;
dev->adap.owner		= THIS_MODULE;
dev->adap.class		= I2C_CLASS_HWMON;
dev->adap.algo		= &smbus_algorithm;
dev->adap.algo_data	= dev;
dev->adap.dev.parent	= &hdev->dev;
snprintf(dev->adap.name, sizeof(dev->adap.name),
"CP2112 SMBus Bridge on hiddev%d", hdev->minor);
dev->hwversion = buf[2];
init_waitqueue_head(&dev->wait);

hid_device_io_start(hdev);
ret = i2c_add_adapter(&dev->adap);
hid_device_io_stop(hdev);

if (ret) {
hid_err(hdev, "error registering i2c adapter\n");
goto err_power_normal;
}

hid_dbg(hdev, "adapter registered\n");

dev->gc.label			= "cp2112_gpio";
dev->gc.direction_input		= cp2112_gpio_direction_input;
dev->gc.direction_output	= cp2112_gpio_direction_output;
dev->gc.set			= cp2112_gpio_set;
dev->gc.get			= cp2112_gpio_get;
dev->gc.base			= -1;
dev->gc.ngpio			= 8;
dev->gc.can_sleep		= 1;
dev->gc.parent			= &hdev->dev;

ret = gpiochip_add_data(&dev->gc, dev);
if (ret < 0) {
hid_err(hdev, "error registering gpio chip\n");
goto err_free_i2c;
}

ret = sysfs_create_group(&hdev->dev.kobj, &cp2112_attr_group);
if (ret < 0) {
hid_err(hdev, "error creating sysfs attrs\n");
goto err_gpiochip_remove;
}

chmod_sysfs_attrs(hdev);
hid_hw_power(hdev, PM_HINT_NORMAL);

ret = gpiochip_irqchip_add(&dev->gc, &cp2112_gpio_irqchip, 0,
handle_simple_irq, IRQ_TYPE_NONE);
if (ret) {
dev_err(dev->gc.parent, "failed to add IRQ chip\n");
goto err_sysfs_remove;
}

return ret;

err_sysfs_remove:
sysfs_remove_group(&hdev->dev.kobj, &cp2112_attr_group);
err_gpiochip_remove:
gpiochip_remove(&dev->gc);
err_free_i2c:
i2c_del_adapter(&dev->adap);
err_power_normal:
hid_hw_power(hdev, PM_HINT_NORMAL);
err_hid_close:
hid_hw_close(hdev);
err_hid_stop:
hid_hw_stop(hdev);
return ret;
}

struct nfs_open_context *nfs_find_open_context(struct inode *inode, struct rpc_cred *cred, int mode)
 {
 	struct nfs_inode *nfsi = NFS_I(inode);
 	struct nfs_open_context *pos, *ctx = NULL;

	spin_lock(&inode->i_lock);
	list_for_each_entry(pos, &nfsi->open_files, list) {
		if (cred != NULL && pos->cred != cred)
			continue;
		if ((pos->mode & mode) == mode) {
			ctx = get_nfs_open_context(pos);
			break;
		}
	}
	spin_unlock(&inode->i_lock);
	return ctx;
}

_WM_ParseNewHmi(uint8_t *hmi_data, uint32_t hmi_size) {
uint32_t hmi_tmp = 0;
uint8_t *hmi_base = hmi_data;
uint16_t hmi_bpm = 0;
uint16_t hmi_division = 0;

  uint32_t hmi_duration_secs = 0;
uint32_t hmi_track_cnt = 0;
uint32_t *hmi_track_offset = NULL;
uint32_t i = 0;
uint32_t j = 0;
uint8_t *hmi_addr = NULL;
uint32_t *hmi_track_header_length = NULL;
struct _mdi *hmi_mdi = NULL;
uint32_t tempo_f = 5000000.0;
uint32_t *hmi_track_end = NULL;
uint8_t hmi_tracks_ended = 0;
uint8_t *hmi_running_event = NULL;
uint32_t setup_ret = 0;
uint32_t *hmi_delta = NULL;

uint32_t smallest_delta = 0;
uint32_t subtract_delta = 0;

uint32_t sample_count = 0;
float sample_count_f = 0;
float sample_remainder = 0;

float samples_per_delta_f = 0.0;

struct _note {
uint32_t length;
uint8_t channel;
} *note;

    //FIXME: This needs to be used for sanity check.
    UNUSED(hmi_size);

if (memcmp(hmi_data, "HMI-MIDISONG061595", 18)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_HMI, NULL, 0);
return NULL;
}

//FIXME: Unsure if this is correct but it seems to be the only offset that plays the files at what appears to be the right speed.
hmi_bpm = hmi_data[212];

hmi_division = 60;

hmi_track_cnt = hmi_data[228];

hmi_mdi = _WM_initMDI();

_WM_midi_setup_divisions(hmi_mdi, hmi_division);

if ((_WM_MixerOptions & WM_MO_ROUNDTEMPO)) {
tempo_f = (float) (60000000 / hmi_bpm) + 0.5f;
} else {
tempo_f = (float) (60000000 / hmi_bpm);
}
samples_per_delta_f = _WM_GetSamplesPerTick(hmi_division, (uint32_t)tempo_f);

_WM_midi_setup_tempo(hmi_mdi, (uint32_t)tempo_f);

hmi_track_offset = (uint32_t *)malloc(sizeof(uint32_t) * hmi_track_cnt);
hmi_track_header_length = malloc(sizeof(uint32_t) * hmi_track_cnt);
hmi_track_end = malloc(sizeof(uint32_t) * hmi_track_cnt);
hmi_delta = malloc(sizeof(uint32_t) * hmi_track_cnt);
note = malloc(sizeof(struct _note) * 128 * hmi_track_cnt);
hmi_running_event = malloc(sizeof(uint8_t) * 128 * hmi_track_cnt);

hmi_data += 370;

smallest_delta = 0xffffffff;

if (hmi_size < (370 + (hmi_track_cnt * 17))) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_HMI, "file too short", 0);
goto _hmi_end;
}

hmi_track_offset[0] = *hmi_data; // To keep Xcode happy

for (i = 0; i < hmi_track_cnt; i++) {
hmi_track_offset[i] = *hmi_data++;
hmi_track_offset[i] += (*hmi_data++ << 8);
hmi_track_offset[i] += (*hmi_data++ << 16);
hmi_track_offset[i] += (*hmi_data++ << 24);

if (hmi_size < (hmi_track_offset[i] + 0x5a + 4)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_HMI, "file too short", 0);
goto _hmi_end;
}

hmi_addr = hmi_base + hmi_track_offset[i];

if (memcmp(hmi_addr, "HMI-MIDITRACK", 13)) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_HMI, NULL, 0);
goto _hmi_end;
}

hmi_track_header_length[i] = hmi_addr[0x57];
hmi_track_header_length[i] += (hmi_addr[0x58] << 8);
hmi_track_header_length[i] += (hmi_addr[0x59] << 16);
hmi_track_header_length[i] += (hmi_addr[0x5a] << 24);

hmi_addr += hmi_track_header_length[i];
hmi_track_offset[i] += hmi_track_header_length[i];

// Get tracks initial delta and set its samples_till_next;
hmi_delta[i] = 0;
if (*hmi_addr > 0x7f) {
do {
hmi_delta[i] = (hmi_delta[i] << 7) + (*hmi_addr & 0x7f);
hmi_addr++;
hmi_track_offset[i]++;
} while (*hmi_addr > 0x7f);
}
hmi_delta[i] = (hmi_delta[i] << 7) + (*hmi_addr & 0x7f);
hmi_track_offset[i]++;
hmi_addr++;

// Find smallest delta to work with
if (hmi_delta[i] < smallest_delta) {
smallest_delta = hmi_delta[i];
}

hmi_track_end[i] = 0;
hmi_running_event[i] = 0;

for (j = 0; j < 128; j++) {
hmi_tmp = (128 * i) + j;
note[hmi_tmp].length = 0;
note[hmi_tmp].channel = 0;
}
}

subtract_delta = smallest_delta;
sample_count_f= (((float) smallest_delta * samples_per_delta_f) + sample_remainder);

sample_count = (uint32_t) sample_count_f;
sample_remainder = sample_count_f - (float) sample_count;

hmi_mdi->events[hmi_mdi->event_count - 1].samples_to_next += sample_count;
hmi_mdi->extra_info.approx_total_samples += sample_count;

while (hmi_tracks_ended < hmi_track_cnt) {
smallest_delta = 0;
for (i = 0; i < hmi_track_cnt; i++) {
if (hmi_track_end[i]) continue;

// first check to see if any active notes need turning off.
for (j = 0; j < 128; j++) {
hmi_tmp = (128 * i) + j;
if (note[hmi_tmp].length) {
note[hmi_tmp].length -= subtract_delta;
if (note[hmi_tmp].length) {
if ((!smallest_delta) || (smallest_delta > note[hmi_tmp].length)) {
smallest_delta = note[hmi_tmp].length;
}
} else {
_WM_midi_setup_noteoff(hmi_mdi, note[hmi_tmp].channel, j, 0);
}
}
}

if (hmi_delta[i]) {
hmi_delta[i] -= subtract_delta;
if (hmi_delta[i]) {
if ((!smallest_delta) || (smallest_delta > hmi_delta[i])) {
smallest_delta = hmi_delta[i];
}
continue;
}
}

do {
hmi_data = hmi_base + hmi_track_offset[i];
hmi_delta[i] = 0;

if (hmi_data[0] == 0xfe) {
// HMI only event of some sort.
if (hmi_data[1] == 0x10) {
hmi_tmp = (hmi_data[4] + 5);
hmi_data += hmi_tmp;
hmi_track_offset[i] += hmi_tmp;
} else if (hmi_data[1] == 0x15) {
hmi_data += 4;
hmi_track_offset[i] += 4;
}
hmi_data += 4;
hmi_track_offset[i] += 4;
} else {
                    if ((setup_ret = _WM_SetupMidiEvent(hmi_mdi,hmi_data,hmi_running_event[i])) == 0) {
goto _hmi_end;
}
if ((hmi_data[0] == 0xff) && (hmi_data[1] == 0x2f) && (hmi_data[2] == 0x00)) {
hmi_track_end[i] = 1;
hmi_tracks_ended++;
for(j = 0; j < 128; j++) {
hmi_tmp = (128 * i) + j;
if (note[hmi_tmp].length) {
_WM_midi_setup_noteoff(hmi_mdi, note[hmi_tmp].channel, j, 0);
note[hmi_tmp].length = 0;
}
}
goto _hmi_next_track;
}
// Running event
// 0xff does not alter running event
if ((*hmi_data == 0xF0) || (*hmi_data == 0xF7)) {
// Sysex resets running event data
hmi_running_event[i] = 0;
} else if (*hmi_data < 0xF0) {
// MIDI events 0x80 to 0xEF set running event
if (*hmi_data >= 0x80) {
hmi_running_event[i] = *hmi_data;
}
}
if ((hmi_running_event[i] & 0xf0) == 0x90) {
// note on has extra data to specify how long the note is.
if (*hmi_data > 127) {
hmi_tmp = hmi_data[1];
} else {
hmi_tmp = *hmi_data;
}
hmi_tmp += (i * 128);

note[hmi_tmp].channel = hmi_running_event[i] & 0xf;

hmi_data += setup_ret;
hmi_track_offset[i] += setup_ret;

note[hmi_tmp].length = 0;
                        if (*hmi_data > 0x7f) {
do {
note[hmi_tmp].length = (note[hmi_tmp].length << 7) | (*hmi_data & 0x7F);
hmi_data++;
hmi_track_offset[i]++;
} while (*hmi_data > 0x7F);
}
note[hmi_tmp].length = (note[hmi_tmp].length << 7) | (*hmi_data & 0x7F);
hmi_data++;
hmi_track_offset[i]++;

if (note[hmi_tmp].length) {
if ((!smallest_delta) || (smallest_delta > note[hmi_tmp].length)) {
smallest_delta = note[hmi_tmp].length;
}
} else {
_WM_midi_setup_noteoff(hmi_mdi, note[hmi_tmp].channel, j, 0);
}

} else {
hmi_data += setup_ret;
hmi_track_offset[i] += setup_ret;
}
}

// get track delta
// hmi_delta[i] = 0; // set at start of loop
                if (*hmi_data > 0x7f) {
do {
hmi_delta[i] = (hmi_delta[i] << 7) | (*hmi_data & 0x7F);
hmi_data++;
hmi_track_offset[i]++;
} while (*hmi_data > 0x7F);
}
hmi_delta[i] = (hmi_delta[i] << 7) | (*hmi_data & 0x7F);
hmi_data++;
hmi_track_offset[i]++;
} while (!hmi_delta[i]);
if ((!smallest_delta) || (smallest_delta > hmi_delta[i])) {
smallest_delta = hmi_delta[i];
}

_hmi_next_track:
hmi_tmp = 0;
UNUSED(hmi_tmp);
}

// convert smallest delta to samples till next
subtract_delta = smallest_delta;
sample_count_f= (((float) smallest_delta * samples_per_delta_f) + sample_remainder);

sample_count = (uint32_t) sample_count_f;
sample_remainder = sample_count_f - (float) sample_count;

hmi_mdi->events[hmi_mdi->event_count - 1].samples_to_next += sample_count;
hmi_mdi->extra_info.approx_total_samples += sample_count;
}

if ((hmi_mdi->reverb = _WM_init_reverb(_WM_SampleRate, _WM_reverb_room_width, _WM_reverb_room_length, _WM_reverb_listen_posx, _WM_reverb_listen_posy)) == NULL) {
_WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_MEM, "to init reverb", 0);
goto _hmi_end;
}

hmi_mdi->extra_info.current_sample = 0;
hmi_mdi->current_event = &hmi_mdi->events[0];
hmi_mdi->samples_to_mix = 0;
hmi_mdi->note = NULL;

_WM_ResetToStart(hmi_mdi);

_hmi_end:
free(hmi_track_offset);
free(hmi_track_header_length);
free(hmi_track_end);
free(hmi_delta);
free(note);
free(hmi_running_event);

if (hmi_mdi->reverb) return (hmi_mdi);
_WM_freeMDI(hmi_mdi);
return 0;
}

char *FLTGetIsLikeComparisonExpression(FilterEncodingNode *psFilterNode)
{
  const size_t bufferSize = 1024;
  char szBuffer[1024];
  char szTmp[256];
  char *pszValue = NULL;

  const char *pszWild = NULL;
  const char *pszSingle = NULL;
  const char *pszEscape = NULL;
  int  bCaseInsensitive = 0;

  int nLength=0, i=0, iTmp=0;
  FEPropertyIsLike* propIsLike;


  if (!psFilterNode || !psFilterNode->pOther || !psFilterNode->psLeftNode ||
      !psFilterNode->psRightNode || !psFilterNode->psRightNode->pszValue)
    return NULL;

  propIsLike = (FEPropertyIsLike *)psFilterNode->pOther;
  pszWild = propIsLike->pszWildCard;
  pszSingle = propIsLike->pszSingleChar;
  pszEscape = propIsLike->pszEscapeChar;
  bCaseInsensitive = propIsLike->bCaseInsensitive;

  if (!pszWild || strlen(pszWild) == 0 ||
      !pszSingle || strlen(pszSingle) == 0 ||
      !pszEscape || strlen(pszEscape) == 0)
    return NULL;


  /* -------------------------------------------------------------------- */
  /*      Use operand with regular expressions.                           */
  /* -------------------------------------------------------------------- */
  szBuffer[0] = '\0';
  sprintf(szTmp, "%s", " (\"[");
  szTmp[4] = '\0';

  strlcat(szBuffer, szTmp, bufferSize);

  /* attribute */
  strlcat(szBuffer, psFilterNode->psLeftNode->pszValue, bufferSize);
  szBuffer[strlen(szBuffer)] = '\0';

  /*#3521 */
  if(bCaseInsensitive == 1)
    sprintf(szTmp, "%s", "]\" ~* /");
  else
    sprintf(szTmp, "%s", "]\" =~ /");
  szTmp[7] = '\0';
  strlcat(szBuffer, szTmp, bufferSize);
  szBuffer[strlen(szBuffer)] = '\0';


   pszValue = psFilterNode->psRightNode->pszValue;
   nLength = strlen(pszValue);

   iTmp =0;
   if (nLength > 0 && pszValue[0] != pszWild[0] &&
      pszValue[0] != pszSingle[0] &&
      pszValue[0] != pszEscape[0]) {
    szTmp[iTmp]= '^';
    iTmp++;
  }
  for (i=0; i<nLength; i++) {
    if (pszValue[i] != pszWild[0] &&
        pszValue[i] != pszSingle[0] &&
        pszValue[i] != pszEscape[0]) {
      szTmp[iTmp] = pszValue[i];
      iTmp++;
      szTmp[iTmp] = '\0';
    } else if  (pszValue[i] == pszSingle[0]) {
      szTmp[iTmp] = '.';
      iTmp++;
      szTmp[iTmp] = '\0';
    } else if  (pszValue[i] == pszEscape[0]) {
      szTmp[iTmp] = '\\';
      iTmp++;
      szTmp[iTmp] = '\0';

    } else if (pszValue[i] == pszWild[0]) {
      /* strcat(szBuffer, "[0-9,a-z,A-Z,\\s]*"); */
      /* iBuffer+=17; */
      szTmp[iTmp++] = '.';
      szTmp[iTmp++] = '*';
      szTmp[iTmp] = '\0';
    }
  }
  szTmp[iTmp] = '/';
  szTmp[++iTmp] = '\0';

  strlcat(szBuffer, szTmp, bufferSize);
  strlcat(szBuffer, ")", bufferSize);
  return msStrdup(szBuffer);
}

