void LauncherView::ButtonPressed(views::Button* sender,
const views::Event& event) {
// Do not handle mouse release during drag.
if (dragging_)
return;

  if (sender == overflow_button_)
    ShowOverflowMenu();

if (!delegate_)
return;
int view_index = view_model_->GetIndexOfView(sender);
// May be -1 while in the process of animating closed.
if (view_index == -1)
return;

switch (model_->items()[view_index].type) {
case TYPE_TABBED:
case TYPE_APP_PANEL:
case TYPE_APP_SHORTCUT:
case TYPE_PLATFORM_APP:
delegate_->ItemClicked(model_->items()[view_index], event.flags());
break;

case TYPE_APP_LIST:
Shell::GetInstance()->ToggleAppList();
break;

case TYPE_BROWSER_SHORTCUT:
if (event.flags() & ui::EF_CONTROL_DOWN)
delegate_->CreateNewWindow();
else
delegate_->CreateNewTab();
break;
}
}

long mkvparser::UnserializeString(IMkvReader* pReader, long long pos,
                                  long long size_, char*& str) {
delete[] str;
str = NULL;

  if (size_ >= LONG_MAX)  // we need (size+1) chars
return E_FILE_FORMAT_INVALID;

  const long size = static_cast<long>(size_);

  str = new (std::nothrow) char[size + 1];
if (str == NULL)
    return -1;

unsigned char* const buf = reinterpret_cast<unsigned char*>(str);

const long status = pReader->Read(pos, size, buf);

if (status) {
delete[] str;
str = NULL;


return status;
}

  str[size] = '\0';
  return 0;  // success
}

static void perf_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
struct syscall_metadata *sys_data;
struct syscall_trace_exit *rec;
struct hlist_head *head;
int syscall_nr;
int rctx;
int size;

syscall_nr = trace_get_syscall_nr(current, regs);
	if (syscall_nr < 0)
return;
if (!test_bit(syscall_nr, enabled_perf_exit_syscalls))
return;

sys_data = syscall_nr_to_meta(syscall_nr);
if (!sys_data)
return;

head = this_cpu_ptr(sys_data->exit_event->perf_events);
if (hlist_empty(head))
return;

/* We can probably do that at build time */
size = ALIGN(sizeof(*rec) + sizeof(u32), sizeof(u64));
size -= sizeof(u32);

rec = (struct syscall_trace_exit *)perf_trace_buf_prepare(size,
sys_data->exit_event->event.type, regs, &rctx);
if (!rec)
return;

rec->nr = syscall_nr;
rec->ret = syscall_get_return_value(current, regs);
perf_trace_buf_submit(rec, size, rctx, 0, 1, regs, head, NULL);
}

void PartialMagnificationController::CreateMagnifierWindow() {
  if (zoom_widget_)
return;

  aura::Window* root_window = GetCurrentRootWindow();
  if (!root_window)
return;

root_window->AddObserver(this);

gfx::Point mouse(
root_window->GetHost()->dispatcher()->GetLastMouseLocationInRoot());

  zoom_widget_ = new views::Widget;
views::Widget::InitParams params(
views::Widget::InitParams::TYPE_WINDOW_FRAMELESS);
